/* ===========================================================================
 * Game Boy Emulation tab, area 6 of eight: Cartridges and mappers
 * gbMappersEmulationTabHTML(d) returns this area's HTML; the tab's composer in
 * gb-emulation-tab.js calls every area in order (2 November 2026: the tab
 * was split into area files so a builder can read one area at a time).
 * Loaded by a plain <script src> tag (the site must open over file://).
 * =========================================================================== */

function gbMappersEmulationTabHTML(d) {
  return '<div class="gbemu-area" id="gbemu-area-mappers">' +

  '<section class="sect gbemu-area-head" id="gbemu-area-mappers-head"><h3 class="sect-h">Area 6 of eight: Cartridges and mappers</h3>' +
    '<p class="gbemu-key">The cartridge: the header bytes, the rules every mapper shares, MBC1, MBC2, MBC3 and its clock, MBC5, no mapper, the other licensed chips and the boards named per file (appendix H).</p>' +
    '<p class="hw-readable">This area is the file <code>gb-mappers-emulation-tab.js</code>, one of the eight area files that together make the Game Boy Emulation tab. It can be read on its own; the build checklist is in the first area, and the rule for what a build must implement is beside it.</p>' +
    '<p class="hw-readable"><b>Where the rest of this page is.</b> When a sentence here points to a section or appendix that is not in this area, it is in one of these files (the links work on the assembled page):</p><ul class="gbemu-bullets"><li><b>Overview, build checklist and interface</b> (<code>gb-machine-emulation-tab.js</code>): <a href="#gbe-m1">1. Clocks, map, and one phase that matters</a> <a href="#gbe-m3">3. Where the machine starts</a> <a href="#gbe-gaps">24. What this page does not cover</a></li><li><b>Processor</b> (<code>gb-cpu-emulation-tab.js</code>): <a href="#gbe-m2">2. The processor</a> <a href="#gbe-ops">Appendix D. The instruction set</a></li><li><b>Memory, timer, interrupts, transfers, serial, pad</b> (<code>gb-memory-emulation-tab.js</code>): <a href="#gbe-m4">4. Timer, DMA, interrupt line</a> <a href="#gbe-hw">5. What a real Game Boy settled</a> <a href="#gbe-regs">Appendix A. Every register, every bit</a></li><li><b>Picture</b> (<code>gb-ppu-emulation-tab.js</code>): <a href="#gbe-m5">6. The sprite scan</a> <a href="#gbe-1">7. The decision that decides everything</a> <a href="#gbe-2">8. Step the machine by dots</a> <a href="#gbe-3">9. The fetcher</a> <a href="#gbe-4">10. The two FIFOs</a> <a href="#gbe-5">11. The window is a separate machine</a> <a href="#gbe-6">12. Sprites stall the pipeline</a> <a href="#gbe-7">13. Writes that land mid-line</a> <a href="#gbe-8">14. Interrupts, blocking, power</a> <a href="#gbe-addr">Appendix C. Tile, map and object addressing</a> <a href="#gbe-pipe">Appendix E. The picture pipeline, in numbers</a></li><li><b>Sound</b> (<code>gb-apu-emulation-tab.js</code>): <a href="#gbe-s1">15. The sound unit is not on the processor&rsquo;s clock</a> <a href="#gbe-s2">16. The square channels</a> <a href="#gbe-s3">17. Wave, noise, and power</a> <a href="#gbe-sound-regs">Appendix B. The sound registers, and the primitives the refinements modify</a></li><li><b>Super Game Boy and link devices</b> (<code>gb-sgb-emulation-tab.js</code>): <a href="#gbe-sgb">Appendix A, continued: the Super Game Boy and the link-port devices</a></li><li><b>Tests and scores</b> (<code>gb-acceptance-emulation-tab.js</code>): <a href="#gbe-9">18. Traps that cost us weeks</a> <a href="#gbe-10">19. What to test with, in order</a> <a href="#gbe-11">20. How to measure a change</a> <a href="#gbe-score">21. The score, and what a score is worth</a> <a href="#gbe-unwinnable">22. Rows nobody can win honestly</a> <a href="#gbe-12">23. The evidence</a> <a href="#gbe-labels">Appendix F. Labels, flexibility, and what is not established</a> <a href="#gbe-verify">Appendix G. The verification scorecard</a></li></ul>' +
  '</section>' +
  '<div class="gbemu-toc"><b>In this area</b><a href="#gbe-mappers">Appendix H. The cartridge mappers, register by register</a></div>' +

    '<section class="sect" id="gbe-mappers"><h3 class="sect-h">Appendix H. The cartridge mappers, register by register</h3>' +
    '<p class="hw-readable">Which mapper chips a cartridge may carry is in section 1; their bank-register layouts are not, and that is what this appendix supplies. A reader who already has that documentation does not need it; a reader who does not cannot load a banked cartridge at all, and every stage of the ladder in G.4 above the first is unreachable.</p>' +
    '<p class="gbemu-key"><b>Thirty-four rows of the 264 sit behind this appendix</b> (Mooneye <code>mbc1</code> 13, <code>mbc2</code> 7, <code>mbc5</code> 8, cpp 3, ax6 3) and <b>the important half of them fails silently.</b> A wrong mapper does not crash and does not print anything. It returns the wrong bank, and the title runs until it reads a table that is not there. <b>Budget for this: the failure you are looking for is a game that works for twenty minutes and then draws garbage in one room.</b> H.8 says which cartridge catches which.</p>' +
    '<p class="hw-readable"><b>Words and units in this appendix.</b> The <b>low window</b> is <code>0x0000</code>&ndash;<code>0x3FFF</code>, the <b>high window</b> <code>0x4000</code>&ndash;<code>0x7FFF</code> and the <b>RAM window</b> <code>0xA000</code>&ndash;<code>0xBFFF</code>. A <b>program bank</b> is 16&nbsp;KiB of the image; a bank number counts program banks from 0 at the image&rsquo;s first byte. A <b>RAM bank</b> is 8&nbsp;KiB of cartridge RAM, counted from 0. <code>rom_banks</code> is the program bank count of Rule H.1/2, and the <b>cartridge mask</b> is <code>rom_banks &minus; 1</code>. A <b>mapper write</b> is a processor write to <code>0x0000</code>&ndash;<code>0x7FFF</code> (Rule H.2/1). Register ranges are written in hexadecimal without the <code>0x</code> where a table says so. &ldquo;<code>v</code>&rdquo; is the byte written. The <b>zero-to-one correction</b> is the step &ldquo;if the bank number is 0, use 1&rdquo;.</p>' +
    '<div class="gbemu-why"><b>Why.</b> <b>MECHANISM</b> throughout unless a row says otherwise: this is transcription from the cartridge paths of the core the rest of this page describes, and what verifies it is the 34 rows above plus every commercial title in the corpus. <b>Where this core does something an implementer could not derive, or does something inconsistent, the row says so rather than presenting it as the rule.</b></div>' +

    '<h4 class="gbemu-sub">H.1: The three header bytes, and nothing else</h4>' +
    '<div class="gbemu-rule" id="gbr-H-1-1"><b>Rule H.1/1.</b> Exactly three bytes of the cartridge header select the mapper and the memory sizes: <code>0x0147</code>, <code>0x0148</code> and <code>0x0149</code> (table below). <b>They are read once, when the image is loaded, and never again.</b> The header checksum (Rule H.1/6) and the image&rsquo;s own content (H.10, H.11) change the choice only in the cases those rules name. An image shorter than <code>0x150</code> bytes is not parsed at all and runs as a flat 32&nbsp;KiB image with no mapper.' +
    '<table class="gbemu-table"><thead><tr><th>Byte (header offset, hex)</th><th>Meaning</th></tr></thead><tbody>' +
    '<tr><td><code>0x0147</code></td><td>Cartridge type: selects the mapper, and declares battery, real-time clock and rumble (Rule H.1/5)</td></tr>' +
    '<tr><td><code>0x0148</code></td><td>Program size: <b><code>banks = 2 &lt;&lt; value</code></b> for values 0 to 8, giving 2 to 512 banks of 16&nbsp;KiB. <b>Any other value is treated as 2 banks (32&nbsp;KiB)</b>, which covers the three unofficial codes in circulation. Rule H.1/2 widens the count</td></tr>' +
    '<tr><td><code>0x0149</code></td><td>RAM size: see Rule H.1/7. <b>MBC2 ignores this byte entirely</b>: its RAM lives inside the mapper and is <b>512 &times; 4 bits (512 <em>nibbles</em>, not 512 bytes</b>, mirrored sixteen times, upper nibble reading as 1s). Implementing it as 512 bytes instead is precisely what H.4 prices at <b>three of Mooneye&rsquo;s seven <code>mbc2</code> rows</b>. <b>H.4 is the definition; this row is a pointer to it.</b></td></tr>' +
    '</tbody></table></div>' +

    '<div class="gbemu-rule" id="gbr-H-1-2"><b>Rule H.1/2.</b> The program bank count <code>rom_banks</code> is fixed at load, in this order:' +
    '<ol class="gbemu-steps">' +
    '<li>From the header: <code>banks = 2 &lt;&lt; value</code> when the byte at <code>0x0148</code> is 0 to 8; otherwise <code>banks = 2</code>. <b>Except</b> for the boards of Rules H.1/3 and H.1/4 and for MMM01 (Rule H.10/12): their count is the file length rounded up to a power of two, and <code>0x0148</code> is not read for it, so it can be smaller than the header&rsquo;s (a 64&nbsp;KiB type <code>00</code> image declaring <code>05</code> gets 4 banks). Step 2 then leaves it as it is.</li>' +
    '<li>If the cartridge has a mapper (the mapper chosen by Rules H.1/3 to H.1/5, H.10 or H.11 is not &ldquo;none&rdquo;), <b>widen, never narrow, to the file</b>: while <code>banks</code> is less than 512 and <code>banks &times; 16&nbsp;KiB</code> is less than the image length in bytes, double <code>banks</code>.</li>' +
    '<li><b>Cartridges with no mapper are never widened</b>: type <code>00</code> on an image of 32&nbsp;KiB or less, types <code>08</code> and <code>09</code>, and every type left with no mapper keep step 1&rsquo;s count. They have no bank register, so the low window is bank 0 and the high window bank 1 whatever the count says.</li>' +
    '<li>The cartridge mask is <code>banks &minus; 1</code>. A program read whose byte offset in the image (bank &times; <code>0x4000</code> + the address&rsquo;s offset inside its window) is at or past the end of the image returns <code>0xFF</code>, with or without a mapper (Rule H.2/4).</li>' +
    '</ol></div>' +
    '<div class="gbemu-example"><b>Example.</b> An MBC5 image of 1&nbsp;MiB (1,048,576 bytes) whose <code>0x0148</code> is <code>03</code>: step 1 gives 2 &lt;&lt; 3 = 16 banks (256&nbsp;KiB); step 2 doubles to 32 and then to 64, and stops because 64 &times; 16&nbsp;KiB = 1&nbsp;MiB is not less than the length; the mask is 63 (<code>0x3F</code>). The same image with <code>0x0148</code> = <code>06</code> (128 banks, 2&nbsp;MiB, an over-declaring header) stays at 128 banks, mask 127: bank 100 (<code>0x64</code>) is selectable, its offset 100 &times; 16&nbsp;KiB = 1,600&nbsp;KiB is past the end of the 1&nbsp;MiB image, and every read of it returns <code>0xFF</code>. A type <code>00</code> image of 16&nbsp;KiB keeps 2 banks: its high window (bank 1, image offsets <code>0x4000</code>&ndash;<code>0x7FFF</code>) lies past the end and reads <code>0xFF</code>.</div>' +
    '<div class="gbemu-why"><b>Why.</b> <b>The bank count is always a power of two, and that is what makes <code>banks &minus; 1</code> a valid mask everywhere below.</b> The header byte is data the game never reads; the mapper drives all of its bank lines and the board wires as many as its chip has, so a header that under-states the chip must not shrink your mask, or high banks fold onto low ones and the title draws a black screen. MECHANISM. A header that <em>over</em>-declares still produces offsets past the end of the image, and those reads return <code>0xFF</code> rather than faulting. Build that bound in; homebrew over-declares constantly. That cartridges with no mapper keep the header&rsquo;s count is MECHANISM, read from our source (the widening runs only when a mapper is present).</div>' +

    '<div class="gbemu-rule" id="gbr-H-1-3"><b>Rule H.1/3.</b> <b>Type <code>00</code> on an image larger than 32&nbsp;KiB</b> runs as <b>MBC3</b>, with no clock, no battery, the RAM size the header&rsquo;s <code>0x0149</code> declares (usually none), and the bank count taken from the file length, rounded up to a power of two: the smallest of 2, 4, 8, &hellip; 512 banks whose total covers the file.</div>' +
    '<div class="gbemu-example"><b>Example.</b> A type <code>00</code> image of 64&nbsp;KiB runs as MBC3 with 4 banks; one of 96&nbsp;KiB (98,304 bytes) with 8 banks (4 banks cover only 64&nbsp;KiB). A type <code>00</code> image of exactly 32&nbsp;KiB is not larger than 32&nbsp;KiB and keeps no mapper.</div>' +
    '<div class="gbemu-why"><b>Why.</b> A board with no mapper can only reach 32&nbsp;KiB, so a bigger image must have had a banking chip, whatever the header says. Unlicensed and prototype cartridges often copied another game&rsquo;s header and left this byte at <code>00</code>: <i>Zuigao Jimi (Top Secret)</i> carries a 32&nbsp;KiB header on a 64&nbsp;KiB image, and run with no mapper it stops right after the boot logo. The dump cannot say which chip it was, so the choice of MBC3 is labelled <b>FITTED</b>: it matches the reference emulator, and for the small bank numbers these games write, MBC1, MBC3 and MBC5 behave the same.</div>' +

    '<div class="gbemu-rule" id="gbr-H-1-4"><b>Rule H.1/4.</b> <b>A type byte that names no chip at all</b> (a value in no row of Rule H.1/5&rsquo;s table) <b>on an image larger than 32&nbsp;KiB</b> runs as <b>MBC1</b>, with no cartridge RAM and the bank count from the file as in Rule H.1/3, if the header passes the header checksum (Rule H.1/6). If the checksum fails, or the image is 32&nbsp;KiB or less, it keeps no mapper. A type byte that does name a chip in that table but loses it to a failed checksum (the six types listed under Rule H.1/5&rsquo;s table) is not covered by this rule: it keeps no mapper.</div>' +
    '<div class="gbemu-example"><b>Example.</b> Type <code>4C</code> (no chip) on a 512&nbsp;KiB image with a passing header: MBC1, 32 banks, no RAM. The same image with a failing header: no mapper, banks 0 and 1 only. Type <code>FF</code> (HuC1) on a 512&nbsp;KiB image with a failing header: no mapper, not MBC1.</div>' +
    '<div class="gbemu-why"><b>Why.</b> Some unlicensed Taiwanese cartridges carry text or program code where this byte would be (their title runs on into it), so it holds a value no chip maker ever assigned. The console never reads it, and a banked image still needs a banking chip. <i>Super Donkey Kong 3</i> runs only on MBC1, and <i>Magic Ball</i> and <i>Binary Monsters II</i> run the same on any of the three. That a failed licensed type keeps no mapper is read from our source (the MBC1 fallback applies only to a type byte that falls through every row).</div>' +

    '<div class="gbemu-rule" id="gbr-H-1-5"><b>Rule H.1/5.</b> The type byte at <code>0x0147</code> selects the mapper:' +
    '<table class="gbemu-table"><thead><tr><th><code>0x0147</code> (hex)</th><th>Mapper</th><th>Also declares</th></tr></thead><tbody>' +
    '<tr><td><code>00</code></td><td>none (MBC3 if the image is over 32&nbsp;KiB, Rule H.1/3)</td><td>none</td></tr>' +
    '<tr><td><code>01 02 03</code></td><td><b>MBC1</b></td><td><code>03</code> battery</td></tr>' +
    '<tr><td><code>05 06</code></td><td><b>MBC2</b></td><td><code>06</code> battery</td></tr>' +
    '<tr><td><code>08 09</code></td><td>none, with RAM declared</td><td><code>09</code> battery. <b>See the trap in H.7</b></td></tr>' +
    '<tr><td><code>0F 10</code></td><td><b>MBC3</b></td><td><b>real-time clock</b> and battery. <b>These two types are the only ones that enable the clock</b></td></tr>' +
    '<tr><td><code>11 12 13</code></td><td><b>MBC3</b>, no clock</td><td><code>13</code> battery</td></tr>' +
    '<tr><td><code>19 1A 1B</code></td><td><b>MBC5</b></td><td><code>1B</code> battery</td></tr>' +
    '<tr><td><code>1C 1D 1E</code></td><td><b>MBC5</b> + rumble</td><td><code>1E</code> battery. The motor bit is reported and is not stripped from the RAM bank: Rule H.6/3</td></tr>' +
    '<tr><td><code>20</code></td><td><b>MBC6</b></td><td>battery; flash (H.10)</td></tr>' +
    '<tr><td><code>22</code></td><td><b>MBC7</b></td><td>battery; accelerometer and serial EEPROM (H.10)</td></tr>' +
    '<tr><td><code>FC</code></td><td><b>Pocket Camera</b></td><td>battery; image sensor (H.10)</td></tr>' +
    '<tr><td><code>FD</code></td><td><b>TAMA5</b></td><td>battery; clock (H.10)</td></tr>' +
    '<tr><td><code>FE</code></td><td><b>HuC3</b></td><td>battery; clock (H.10)</td></tr>' +
    '<tr><td><code>FF</code></td><td><b>HuC1</b></td><td>battery (H.10)</td></tr>' +
    '<tr><td>anything else</td><td><b>none</b> (MBC1 if the image is over 32&nbsp;KiB and its header passes the boot program&rsquo;s checksum, Rule H.1/4)</td><td>see the checksum condition below this table</td></tr>' +
    '</tbody></table>' +
    'The six types <code>20</code> MBC6, <code>22</code> MBC7, <code>FC</code> Pocket Camera, <code>FD</code> TAMA5, <code>FE</code> HuC3 and <code>FF</code> HuC1 name their chip <b>only on a header that passes the boot program&rsquo;s header checksum</b> (Rule H.1/6), as every licensed board must; a header that fails it keeps no mapper. The types of MBC1, MBC2, MBC3 and MBC5 never need it. MMM01 and M161 are recognised from the image rather than this byte (H.10).</div>' +

    '<div class="gbemu-rule" id="gbr-H-1-6"><b>Rule H.1/6. The header checksum, as the boot program computes it.</b>' +
    '<ol class="gbemu-steps">' +
    '<li>Start with an 8-bit value x = 0.</li>' +
    '<li>For each byte from <code>0x0134</code> to <code>0x014C</code> inclusive (the title through the version number, 25 bytes), in address order: subtract the byte from x, then subtract 1, keeping 8 bits.</li>' +
    '<li>The header passes when x equals the byte at <code>0x014D</code>.</li>' +
    '</ol>' +
    'Our core uses this test only to decide the mapper, in the two places named above (Rules H.1/4 and H.1/5).</div>' +
    '<div class="gbemu-example"><b>Example.</b> If all 25 bytes are <code>00</code>, each step subtracts 1, so x = 0 &minus; 25 = &minus;25, which is <code>0xE7</code> in 8 bits: the header passes only if <code>0x014D</code> holds <code>E7</code>. If the first byte is <code>01</code> and the other 24 are <code>00</code>, x = &minus;26 = <code>0xE6</code>.</div>' +
    '<div class="gbemu-why"><b>Why.</b> A real boot program that finds a mismatch stops before the hand-over. MECHANISM, read from our source (both mapper decisions compute it this way).</div>' +

    '<div class="gbemu-rule" id="gbr-H-1-7"><b>Rule H.1/7.</b> The byte at <code>0x0149</code> gives the cartridge RAM (every type except MBC2, Rule H.4/2; MMM01 reads it from its footer header, Rule H.10/11):' +
    '<table class="gbemu-table"><thead><tr><th><code>0x0149</code> (hex)</th><th>Cartridge RAM (bytes)</th><th>Banks of 8&nbsp;KiB (whole banks)</th></tr></thead><tbody>' +
    '<tr><td><code>00</code></td><td>none</td><td>0</td></tr>' +
    '<tr><td><code>01</code></td><td>2&nbsp;KiB (unofficial)</td><td><b>0 whole banks</b>: 2&nbsp;KiB is a quarter of a bank, and the column counts whole ones. <b>And it repeats</b>: a 2&nbsp;KiB chip decodes only the low eleven address lines, so <code>0xA000</code>&ndash;<code>0xBFFF</code> shows the same 2&nbsp;KiB four times, reads and writes alike (offset <code>(address &minus; 0xA000) &amp; 0x7FF</code>)</td></tr>' +
    '<tr><td><code>02</code></td><td>8&nbsp;KiB</td><td>1</td></tr>' +
    '<tr><td><code>03</code></td><td>32&nbsp;KiB</td><td>4</td></tr>' +
    '<tr><td><code>04</code></td><td>128&nbsp;KiB</td><td>16</td></tr>' +
    '<tr><td><code>05</code></td><td>64&nbsp;KiB</td><td>8</td></tr>' +
    '<tr><td>anything else</td><td>none</td><td>0</td></tr>' +
    '</tbody></table>' +
    '<b>Note the order: <code>05</code> is 64&nbsp;KiB and <code>04</code> is 128&nbsp;KiB.</b></div>' +
    '<div class="gbemu-example"><b>Example.</b> With <code>0x0149</code> = <code>01</code>, a write of <code>0x3C</code> to <code>0xA800</code> lands at offset (<code>0x0800</code>) &amp; <code>0x7FF</code> = 0, so a read of <code>0xA000</code>, <code>0xB000</code> or <code>0xB800</code> returns <code>0x3C</code>; <code>0xBFFF</code> reads offset <code>0x7FF</code>.</div>' +
    '<div class="gbemu-why"><b>Why.</b> The 2&nbsp;KiB mirror is MECHANISM. Two unlicensed Color titles test it at power-on and print a RAM error without it. The table is not monotonic and reading it as though it were is a one-line error that gives half of every large save file to the wrong bank.</div>' +

    '<h4 class="gbemu-sub">H.2: The rules every mapper shares</h4>' +
    '<div class="gbemu-rule" id="gbr-H-2-1"><b>Rule H.2/1.</b> <b>Only writes below <code>0x8000</code> reach the mapper&rsquo;s registers</b> (the bank, enable and mode registers of this appendix): these are the mapper writes. Video memory, work RAM, sprite memory and the registers are elsewhere on the map; a write to any of them is not a mapper write and must never be routed to one. A write to the RAM window is not a mapper write either: it goes to the cartridge RAM path of the chip in use (some chips in H.10 keep further registers there).</div>' +
    '<div class="gbemu-rule" id="gbr-H-2-2"><b>Rule H.2/2.</b> <b>RAM enable is the low nibble equalling <code>0x0A</code>, and only that</b>: a write of <code>v</code> to the RAM-enable register enables RAM when <code>(v &amp; 0x0F) == 0x0A</code>, and every other value disables it; <b>the upper nibble is ignored.</b> Same test on all four mappers (MBC1, MBC2, MBC3, MBC5).</div>' +
    '<div class="gbemu-example"><b>Example.</b> <code>0x0A</code>, <code>0x1A</code> and <code>0xFA</code> all enable. <code>0x0B</code>, <code>0x00</code> and <code>0xA0</code> (low nibble 0) all disable.</div>' +
    '<div class="gbemu-rule" id="gbr-H-2-3"><b>Rule H.2/3.</b> <b>A read of cartridge RAM while it is disabled returns <code>0xFF</code>, and a write is dropped silently.</b> Not zero, not the last value, and not a fault.</div>' +
    '<div class="gbemu-rule" id="gbr-H-2-4"><b>Rule H.2/4.</b> <b>A read that resolves past the end of the image, or past the end of the declared RAM, returns <code>0xFF</code>.</b> Bounds-check the final byte offset, not just the bank number. <b>The RAM bank is masked first, then bounds-checked</b>, on every banked mapper (MBC1, MBC3, MBC5, HuC1, HuC3, the camera, MMM01), in this order:' +
    '<ol class="gbemu-steps">' +
    '<li>Take the RAM bank the chip&rsquo;s own rule selects.</li>' +
    '<li>If the declared RAM is one 8&nbsp;KiB bank or less, use bank 0 (the select is ignored entirely); otherwise AND the bank with (declared RAM banks &minus; 1).</li>' +
    '<li>The offset is bank &times; <code>0x2000</code> + (address &minus; <code>0xA000</code>); a chip smaller than one bank uses Rule H.1/7&rsquo;s mirror instead.</li>' +
    '<li>An offset at or past the end of the declared RAM (reached only with no RAM at all) reads <code>0xFF</code> and drops the write.</li>' +
    '</ol></div>' +
    '<div class="gbemu-example"><b>Example.</b> MBC5 with 32&nbsp;KiB of RAM (4 banks): RAM bank register 6 gives 6 &amp; 3 = 2, so <code>0xA010</code> is RAM offset 2 &times; <code>0x2000</code> + <code>0x10</code> = <code>0x4010</code>. With 8&nbsp;KiB (1 bank) the same register value gives bank 0, offset <code>0x0010</code>.</div>' +
    '<div class="gbemu-why"><b>Why.</b> The bank number check and the byte offset check are different checks and only the offset check catches an over-declaring header. Because the declared size is a power of two of whole banks, a masked offset always lands inside it, so &ldquo;past the end of the declared RAM&rdquo; is reached only by a chip smaller than one bank (mirrored across the window, Rule H.1/7) or by no RAM at all. MECHANISM, read from our source (one RAM-bank routine for every mapper).</div>' +
    '<div class="gbemu-rule" id="gbr-H-2-5"><b>Rule H.2/5.</b> <b>The bank registers are not readable.</b> There is no address at which a program can ask which bank is mapped.</div>' +
    '<div class="gbemu-why"><b>Why.</b> Every cartridge that needs to know keeps its own copy in work RAM. A core that makes them readable will never be caught by a test and will be wrong.</div>' +
    '<div class="gbemu-rule" id="gbr-H-2-6"><b>Rule H.2/6.</b> <b>At power-on the primary program bank register holds 1</b> and every other mapper register holds 0: RAM disabled, mode 0, RAM bank 0. The one exception is M161, whose latch holds 0 (slot 0, Rule H.10/15).</div>' +
    '<div class="gbemu-rule" id="gbr-H-2-7"><b>Rule H.2/7.</b> <b>The boot program overlays the bottom of the map and hides the mapper while it runs.</b> If you supply a boot image, the cartridge is invisible at <code>0x0000</code>&ndash;<code>0x00FF</code> until the unmap write lands.</div>' +


    '<h4 class="gbemu-sub">H.3: MBC1</h4>' +
    '<div class="gbemu-rule" id="gbr-H-3-1"><b>Rule H.3/1.</b> MBC1 has four write ranges, and they tile <code>0x0000</code>&ndash;<code>0x7FFF</code> exhaustively: <b>there is no undecoded range on MBC1</b>.' +
    '<table class="gbemu-table"><thead><tr><th>Write address (hex)</th><th>Register</th><th>Width and masking (what is stored)</th></tr></thead><tbody>' +
    '<tr><td><code>0000&ndash;1FFF</code></td><td>RAM enable</td><td>boolean: <code>(v &amp; 0x0F) == 0x0A</code> (Rule H.2/2)</td></tr>' +
    '<tr><td><code>2000&ndash;3FFF</code></td><td><b>BANK1</b>, the primary bank register</td><td><b>5 bits</b>, <code>v &amp; 0x1F</code>, stored raw: the zero-to-one correction is not applied when storing (Rule H.3/2 applies it)</td></tr>' +
    '<tr><td><code>4000&ndash;5FFF</code></td><td><b>BANK2</b>, the secondary register</td><td><b>2 bits</b>, <code>v &amp; 3</code></td></tr>' +
    '<tr><td><code>6000&ndash;7FFF</code></td><td><b>MODE</b></td><td><b>1 bit</b>, <code>v &amp; 1</code></td></tr>' +
    '</tbody></table></div>' +
    '<div class="gbemu-why"><b>Why.</b> Because the four ranges cover the whole of <code>0x0000</code>&ndash;<code>0x7FFF</code>, &ldquo;what does a write outside a defined range do&rdquo; has no case here.</div>' +
    '<div class="gbemu-rule" id="gbr-H-3-2"><b>Rule H.3/2. The bank arithmetic, and the ORDER of its four steps is the thing to get right.</b> For <code>0x4000</code>&ndash;<code>0x7FFF</code> (the high window):' +
    '<ol class="gbemu-steps">' +
    '<li>Mask to the register width: <code>lo = BANK1 &amp; 0x1F</code>.</li>' +
    '<li>The zero-to-one correction, on BANK1 alone: if <code>lo == 0</code>, <code>lo = 1</code>.</li>' +
    '<li>Combine: <code>bank = (BANK2 &lt;&lt; 5) | lo</code>.</li>' +
    '<li>Mask against the cartridge, last: <code>bank = bank &amp; (rom_banks &minus; 1)</code>.</li>' +
    '</ol>' +
    'The same four steps in code:' +
    '<div class="gbemu-pre">lo = BANK1 &amp; 0x1F          # mask to the register width' +
    'if lo == 0: lo = 1          # the zero-to-one correction, on BANK1 ALONE' +
    'bank = (BANK2 &lt;&lt; 5) | lo     # combine' +
    'bank = bank &amp; (rom_banks - 1)   # mask against the cartridge, LAST</div></div>' +
    '<div class="gbemu-example"><b>Example.</b> <b>The zero-to-one correction applies to BANK1 only, never to the combined value.</b> On a 2&nbsp;MiB cartridge (128 banks, mask 127), BANK2 = 1 with BANK1 = 0 selects bank <code>0x21</code>, not <code>0x20</code>. A write of <code>0x20</code> to <code>2000</code> stores 0 (5 bits), which step 2 turns into bank 1. <b>The correction happens BEFORE the cartridge mask, so on a small cartridge the final bank can still be 0.</b> A 32&nbsp;KiB image has a mask of 1; write 2 to BANK1 and the high window shows <em>bank 0</em>. On a 512&nbsp;KiB cartridge (32 banks, mask 31), BANK2 = 3 with BANK1 = 5 gives (3 &lt;&lt; 5) | 5 = <code>0x65</code>, and <code>0x65</code> &amp; 31 = bank 5.</div>' +
    '<div class="gbemu-why"><b>Why.</b> Three consequences, each of which is a Mooneye row. Banks <code>0x00</code>, <code>0x20</code>, <code>0x40</code> and <code>0x60</code> are the four you cannot reach in the high window, and that is the famous MBC1 hole. The small-cartridge bank 0 is correct and it is tested. <b>BANK2 is masked away by the cartridge mask on anything below 1&nbsp;MiB</b>, so on a 512&nbsp;KiB cartridge the secondary register has no effect on cartridge at all and only switches RAM (Rule H.3/4).</div>' +
    '<div class="gbemu-rule" id="gbr-H-3-3"><b>Rule H.3/3. The large-cartridge bank-0 remap, which section 1 alludes to and never specifies.</b> The low window <code>0x0000</code>&ndash;<code>0x3FFF</code> is bank 0 <em>unless</em> this is MBC1 <b>and</b> MODE is 1, in which case it is <code>(BANK2 &lt;&lt; 5) &amp; (rom_banks &minus; 1)</code> (on the multicart variant, Rule H.3/6 instead). <b>Which program sizes make that visible:</b>' +
    '<table class="gbemu-table"><thead><tr><th>Program size (bytes)</th><th>Banks (of 16&nbsp;KiB)</th><th>Low-window banks reachable in mode 1</th></tr></thead><tbody>' +
    '<tr><td>up to 512&nbsp;KiB</td><td>&le; 32</td><td><b>0 only</b>: the mask kills both BANK2 bits, so mode 1 changes nothing in the low window</td></tr>' +
    '<tr><td>1&nbsp;MiB</td><td>64</td><td><b>0 and 32</b>: one BANK2 bit survives</td></tr>' +
    '<tr><td>2&nbsp;MiB and above</td><td>&ge; 128</td><td><b>0, 32, 64, 96</b>: both bits survive</td></tr>' +
    '</tbody></table></div>' +
    '<div class="gbemu-rule" id="gbr-H-3-4"><b>Rule H.3/4. MODE also governs the RAM bank.</b> In mode 0 the RAM bank is forced to 0. In mode 1 it is <code>BANK2 &amp; 3</code>, then masked by the <em>actual</em> bank count derived from the declared RAM size (Rule H.2/4), so a cartridge with 8&nbsp;KiB or less ignores the select lines entirely and always reads bank 0.</div>' +
    '<div class="gbemu-example"><b>Example.</b> 32&nbsp;KiB of RAM (4 banks), BANK2 = 2: mode 1 gives RAM bank 2, mode 0 gives RAM bank 0. 8&nbsp;KiB of RAM, BANK2 = 3, mode 1: RAM bank 0.</div>' +
    '<div class="gbemu-why"><b>Why.</b> The two effects of MODE (Rules H.3/3 and H.3/4) are exclusive in practice. The last masking step is its own Mooneye row (<code>mbc1/ram_64kb</code>); a core that lets a select line through on a one-bank cartridge reads off the end of its own buffer.</div>' +
    '<div class="gbemu-rule" id="gbr-H-3-5"><b>Rule H.3/5. The multicart variant, and how it is detected.</b> Some MBC1 compilation cartridges wire BANK1 four bits wide instead of five, so BANK2 selects one of four 256&nbsp;KiB games and BANK1 picks a bank inside it. <b>There is no header bit for this</b>. It is detected by content, once at load, and an MBC1 cartridge is the multicart variant when both hold:' +
    '<ol class="gbemu-steps">' +
    '<li>The image is exactly 1&nbsp;MiB (1,048,576 bytes) <em>by file length</em>.</li>' +
    '<li>Compare the 48-byte logo at <code>0x0104</code> with the 48 bytes at each of <code>0x40104</code>, <code>0x80104</code> and <code>0xC0104</code>; <b>at least two of those three</b> must match it byte for byte.</li>' +
    '</ol></div>' +
    '<div class="gbemu-rule" id="gbr-H-3-6"><b>Rule H.3/6.</b> On the multicart variant both bank expressions narrow. The high window is <code>(BANK2 &lt;&lt; 4) | (lo &amp; 0x0F)</code>, where <code>lo</code> is the value after Rule H.3/2&rsquo;s steps 1 and 2, then masked by the cartridge as in step 4. The low window is <code>(BANK2 &lt;&lt; 4)</code>, masked by the cartridge, <b>under exactly the same MODE condition as the general rule</b>, that is, <b>in mode 1 only</b>; in mode 0 the low window is bank 0, as it is for every other MBC1 cartridge. So the four game bases 0, 16, 32 and 48 are reachable in mode 1, and mode 0 always shows the menu its global bank 0.</div>' +
    '<div class="gbemu-example"><b>Example.</b> BANK2 = 2, BANK1 = 3: high window bank (2 &lt;&lt; 4) | 3 = 35; low window bank 32 in mode 1 and bank 0 in mode 0. BANK1 = 0 gives <code>lo</code> = 1, so the high window shows 33. BANK1 = <code>0x10</code> is not 0, so step 2 leaves it, and <code>0x10 &amp; 0x0F</code> = 0: the high window shows bank 32, the game&rsquo;s own base.</div>' +
    '<div class="gbemu-why"><b>Why.</b> <b>Read that mode gate literally: it is load-bearing.</b> A low window that followed BANK2 <em>in mode 0 too</em> would break a multicart menu trying to return to global bank 0, the one thing a multicart menu must be able to do. <b>This core&rsquo;s low-window function returns 0 unless the mapper is MBC1 <em>and</em> MODE is 1, and the multicart branch sits inside that gate.</b> <b>Upstream states the same thing in the test itself</b>: <code>multicart_rom_8Mb</code> tabulates its expected low-window banks twice, and the mode-0 table is all zeroes while the mode-1 table is 0, 16, 32, 48. <b>This is the portable-restatement hazard G.7 names</b>: a rule restated without one of its conditions is a different rule, and no number moves to show it.<br><br>' +
    '<b>The detector is a heuristic and this page will not pretend otherwise</b>: it is CONVERGENCE, and the shape is shared with other implementations. Its falsifier is a 1&nbsp;MiB single-game cartridge that happens to repeat its logo, which would be mis-detected; none is known. <b>CONVERGENCE is a statement about where the shape came from, not about whether anything scores it</b>, and this one is scored: <code>mbc1/multicart_rom_8Mb</code> is a board row, it is one of the thirteen <code>mbc1</code> rows, and <b>it passes</b>. Upstream is explicit that it cannot be passed without a detector: its own header says any emulator wanting to pass it &ldquo;must have either heuristics or some configuration to trigger MBC1 multicart mode&rdquo;, because the variant cannot be told from the header. <b>So the detector is CONVERGENCE <em>and</em> scored</b>, and the row is the falsifier&rsquo;s complement: it would fail if the detector stopped firing. That the cartridge mask is applied to both narrowed expressions is read from our source; on a 1&nbsp;MiB image (mask 63) it never changes a value.</div>' +

    '<h4 class="gbemu-sub">H.4: MBC2</h4>' +
    '<p class="hw-readable"><b>MBC2 has one register region and selects between its two registers with an address line.</b> That is the whole of what makes it different, and it is the thing an implementer who pattern-matches from MBC1 gets wrong.</p>' +
    '<div class="gbemu-rule" id="gbr-H-4-1"><b>Rule H.4/1.</b> A mapper write is decoded by its address:' +
    '<table class="gbemu-table"><thead><tr><th>Write address (raw, as the processor puts it on the bus)</th><th>Register</th><th>Width</th></tr></thead><tbody>' +
    '<tr><td><code>addr &lt; 0x4000</code> and <b>bit 8 of the address is CLEAR</b> (<code>addr &amp; 0x0100</code> = 0)</td><td>RAM enable</td><td><code>(v &amp; 0x0F) == 0x0A</code></td></tr>' +
    '<tr><td><code>addr &lt; 0x4000</code> and <b>bit 8 of the address is SET</b> (<code>addr &amp; 0x0100</code> &ne; 0)</td><td>program bank</td><td><b>4 bits</b>, <code>v &amp; 0x0F</code>, with the zero-to-one correction before the cartridge mask, exactly as MBC1 (Rule H.3/2, steps 2 and 4)</td></tr>' +
    '<tr><td><code>0x4000&ndash;0x7FFF</code></td><td><b>nothing at all</b></td><td>The write is discarded. This is a genuinely undecoded range</td></tr>' +
    '</tbody></table>' +
    '<b>The test is <code>addr &amp; 0x0100</code> on the raw address.</b> Four bits means <b>16 banks, 256&nbsp;KiB maximum</b>.</div>' +
    '<div class="gbemu-example"><b>Example.</b> <code>0x2000</code> enables RAM and <code>0x2100</code> sets the bank. <code>0x0100</code> also sets the bank; <code>0x3EFF</code> (bit 8 clear) is a RAM-enable write. A bank write of <code>0x10</code> stores 0, which the correction turns into bank 1.</div>' +
    '<div class="gbemu-why"><b>Why.</b> A loop that writes the bank register by stepping an address will alternate between the two functions if you get the sense backwards.</div>' +
    '<div class="gbemu-rule" id="gbr-H-4-2"><b>Rule H.4/2. The 512&times;4 RAM, in full.</b> MBC2 carries its RAM inside the mapper: <b>512 nibbles, not 512 bytes and not a bank of anything.</b>' +
    '<ul class="gbemu-bullets">' +
    '<li><b>Addressing is <code>addr &amp; 0x1FF</code></b>, so the 512 locations mirror sixteen times across <code>0xA000</code>&ndash;<code>0xBFFF</code>. <b>This one does mirror</b>, like the 2&nbsp;KiB RAM chip in Rule H.1/7 (which repeats four times across the window).</li>' +
    '<li><b>A write stores only the low nibble.</b> The upper four bits of the byte are discarded.</li>' +
    '<li><b>A read returns the stored nibble with <code>0xF0</code> ORed in</b>, so the upper nibble always reads as 1s.</li>' +
    '<li><b>Disabled, it reads <code>0xFF</code> and drops writes</b>, like any other cartridge RAM (Rule H.2/3).</li>' +
    '</ul></div>' +
    '<div class="gbemu-example"><b>Example.</b> RAM enabled: write <code>0x5C</code> to <code>0xA003</code>; it stores <code>0xC</code>. A read of <code>0xA203</code> (<code>0x203 &amp; 0x1FF</code> = <code>0x003</code>) returns <code>0xFC</code>.</div>' +
    '<div class="gbemu-why"><b>Why.</b> The data lines are not connected. <b>This is the silent one.</b> A core that stores the whole byte and returns it passes every boot, loads every save, and differs from hardware only in the upper nibble of every location, which most code never looks at, until one routine uses the byte as a counter and compares it against <code>0xFF</code>. Three of Mooneye&rsquo;s seven <code>mbc2</code> rows are exactly this.</div>' +

    '<h4 class="gbemu-sub">H.5: MBC3, and the clock</h4>' +
    '<div class="gbemu-rule" id="gbr-H-5-1"><b>Rule H.5/1.</b> MBC3&rsquo;s registers:' +
    '<table class="gbemu-table"><thead><tr><th>Write address (hex)</th><th>Register</th><th>Width and masking (what is stored)</th></tr></thead><tbody>' +
    '<tr><td><code>0000&ndash;1FFF</code></td><td>RAM and clock enable: <b>one gate for both</b></td><td><code>(v &amp; 0x0F) == 0x0A</code></td></tr>' +
    '<tr><td><code>2000&ndash;3FFF</code></td><td>program bank</td><td><b>7 bits</b>, <code>v &amp; 0x7F</code> (<b>not 8</b>) with the zero-to-one correction before the cartridge mask. <b>128 banks, 2&nbsp;MiB maximum</b></td></tr>' +
    '<tr><td><code>4000&ndash;5FFF</code></td><td>RAM bank <b>or</b> clock-register select (the <b>selector</b>)</td><td>stored unmasked; Rule H.5/2</td></tr>' +
    '<tr><td><code>6000&ndash;7FFF</code></td><td>the clock latch</td><td>Rule H.5/5</td></tr>' +
    '</tbody></table></div>' +
    '<div class="gbemu-rule" id="gbr-H-5-2"><b>Rule H.5/2. The <code>4000</code> register does two jobs and the gate between them is a width, not a flag.</b> As a RAM bank it has 2 bits, so <b>32&nbsp;KiB is the maximum usable RAM</b> whatever the header declares. <b>The read path decides on the LOW NIBBLE: the upper nibble is not decoded</b>; the write path decides on the <b>whole byte</b>. To match this core byte for byte, a build reproduces both paths exactly as this table gives them:' +
    '<table class="gbemu-table"><thead><tr><th>Selector byte as stored (hex)</th><th>A read of <code>0xA000</code>&ndash;<code>0xBFFF</code></th><th>A write to <code>0xA000</code>&ndash;<code>0xBFFF</code></th></tr></thead><tbody>' +
    '<tr><td>low nibble 0 to 3 (<code>00</code>&ndash;<code>03</code>, <code>10</code>&ndash;<code>13</code>, &hellip; <code>F0</code>&ndash;<code>F3</code>)</td><td>cartridge RAM, bank <code>selector &amp; 3</code> masked to the RAM size (Rules H.2/3, H.2/4)</td><td>cartridge RAM, bank <code>selector &amp; 3</code> masked to the RAM size</td></tr>' +
    '<tr><td>exactly <code>08</code>&ndash;<code>0C</code></td><td>the clock register the low nibble names (Rule H.5/3), the latched copy; <code>0xFF</code> with the gate shut</td><td>that clock register&rsquo;s running counter, masked to its width; dropped with the gate shut</td></tr>' +
    '<tr><td>low nibble 8 to C with a non-zero upper nibble (<code>18</code>&ndash;<code>1C</code>, &hellip; <code>F8</code>&ndash;<code>FC</code>)</td><td>the clock register the low nibble names, as the row above</td><td>cartridge RAM, bank <code>selector &amp; 3</code> masked to the RAM size</td></tr>' +
    '<tr><td>low nibble 4 to 7 or D to F: <code>0x04</code>&ndash;<code>0x07</code> and <code>0x0D</code>&ndash;<code>0x0F</code>, and the same low nibbles under any upper nibble</td><td><code>0xFF</code>, <b>whether or not the gate is open and whether or not RAM exists</b></td><td>cartridge RAM, bank <code>selector &amp; 3</code> masked to the RAM size</td></tr>' +
    '</tbody></table>' +
    'A build that wants a single rule for both paths uses the low nibble for both (the read path).</div>' +
    '<div class="gbemu-example"><b>Example.</b> <code>0x18</code> reads as <code>0x08</code>: with the selector at <code>0x18</code> and the gate open, a read of <code>0xA000</code> returns the clock&rsquo;s seconds register while a write to <code>0xA000</code> lands in cartridge RAM bank 0. With the selector at <code>0x05</code>, a read returns <code>0xFF</code> even with the gate shut and no RAM, and a write (gate open, 32&nbsp;KiB of RAM) lands in RAM bank 1.</div>' +
    '<div class="gbemu-why"><b>Why.</b> The invalid-bank case (<code>0xFF</code> for a selector that names nothing) is one of the three cpp rows. <b>Recorded rather than presented as the rule: in this core the read path and the write path do not use the same gate.</b> The read masks the selector to four bits before testing it; the write tests the stored byte unmasked. <b>NOT ESTABLISHED</b>: nothing we hold reaches the case, no cartridge on the board writes an out-of-range selector, and the asymmetry is in our source as written rather than because anything measured it. <b>What would settle it:</b> a cartridge that sets the selector above <code>0x0F</code>, writes, and reads back. <b>An implementer should make the two paths agree</b>, and should know that choosing either one costs nothing on this board. The low nibble for both is the read path and what the reference declares by repetition (it prints the same bytes for <code>0x10</code>-<code>0x1F</code> as for <code>0x00</code>-<code>0x0F</code>). Read from our source.</div>' +
    '<div class="gbemu-rule" id="gbr-H-5-3"><b>Rule H.5/3. The five clock registers, and their widths on write.</b> Selector <code>0x08</code> is index 0. A write is masked to the register&rsquo;s width before it is stored and a read returns the stored value, so in our core every bit outside a mask reads 0, bits 1 to 5 of <code>0x0C</code> included (not 1, as unused bits of the display and sound registers read).' +
    '<table class="gbemu-table"><thead><tr><th>Selector (hex)</th><th>Register</th><th>Write mask</th></tr></thead><tbody>' +
    '<tr><td><code>0x08</code></td><td>seconds</td><td><code>0x3F</code>: 6 bits</td></tr>' +
    '<tr><td><code>0x09</code></td><td>minutes</td><td><code>0x3F</code>: 6 bits</td></tr>' +
    '<tr><td><code>0x0A</code></td><td>hours</td><td><code>0x1F</code>: 5 bits</td></tr>' +
    '<tr><td><code>0x0B</code></td><td>days, low 8 bits</td><td><code>0xFF</code></td></tr>' +
    '<tr><td><code>0x0C</code></td><td>days bit 8, halt, carry</td><td><b><code>0xC1</code></b>: <b>bit 0</b> is day bit 8, <b>bit 6</b> halts the clock, <b>bit 7</b> is the day-carry flag. Bits 1&ndash;5 do not exist</td></tr>' +
    '</tbody></table></div>' +
    '<div class="gbemu-why"><b>Why.</b> MECHANISM, read from our source (<code>RTC_MASK_WIDTHS</code>). Whether the original returns 0 or 1 in the bits outside a mask is NOT ESTABLISHED in our core&rsquo;s records: no recorded measurement reads those bits.</div>' +
    '<div class="gbemu-rule" id="gbr-H-5-4"><b>Rule H.5/4. The counter.</b> Four behaviours of the counter that no reference states together. The counter is the running copy of the five registers; it advances once per clock second:' +
    '<ul class="gbemu-bullets">' +
    '<li><b>One clock second is 4,194,304 T-cycles</b>, and on Colour hardware the clock stays in <em>wall</em> time across a speed switch, which means <b>its divisor DOUBLES in double speed</b>, to 8,388,608 of the processor&rsquo;s T-cycles, or equivalently the advance per machine cycle halves.</li>' +
    '<li><b>Halt is bit 6 of the last register, and while it is set the counter does not advance at all</b> (the sub-second count stands still too).</li>' +
    '<li><b>Writing the seconds register resets the sub-second divider</b>, so the next second boundary is a full clock second after the write.</li>' +
    '<li>At each clock second the counter steps in this order:' +
    '<ol class="gbemu-steps">' +
    '<li>Seconds: if it reads 59, it becomes 0 and carries into the minutes; otherwise it becomes (seconds + 1) &amp; <code>0x3F</code> and nothing carries.</li>' +
    '<li>If seconds carried, minutes: 59 becomes 0 and carries into the hours; otherwise (minutes + 1) &amp; <code>0x3F</code>, no carry.</li>' +
    '<li>If minutes carried, hours: 23 becomes 0 and carries into the days; otherwise (hours + 1) &amp; <code>0x1F</code>, no carry.</li>' +
    '<li>If hours carried, the 9-bit day counter (low byte plus bit 0 of the last register) adds 1. On 511&rarr;512 it wraps to 0 and <b>sets the carry flag, which is sticky</b>: nothing clears it but a processor write.</li>' +
    '</ol></li>' +
    '</ul>' +
    '<b>Only the exact transitions carry</b> (seconds and minutes on 59&rarr;60, hours on 23&rarr;24). <b>An out-of-range value counts up through its own field width and wraps there with no carry.</b></div>' +
    '<div class="gbemu-example"><b>Example.</b> Load 61 into seconds and it reads 61, 62, 63, 0 on the next three clock seconds, and the minutes never move. Hours loaded with 25 read 26, &hellip; 31, 0, and the days never move. Days at 511 with the hours at 23, minutes 59 and seconds 59: the next clock second gives day 0 with the carry flag set. A core that carries on <code>&gt;= 60</code> gets the first case wrong, and <code>rtc3test</code> is built on it.</div>' +
    '<div class="gbemu-why"><b>Why.</b> <b>Get the direction of the double-speed correction right; the two errors look alike in code.</b> The measurement settles the sign: 59 frames per clock second against <b>30</b> with the clock left in the processor&rsquo;s domain means an uncorrected clock runs <em>fast</em>, by exactly the factor the processor sped up. Halving the divisor would run it <b>four times</b> fast. Section 3 of the Colour page has the measurement. That the halt bit also stops the sub-second count, and the exact order of the carries, are read from our source.</div>' +
    '<div class="gbemu-rule" id="gbr-H-5-5"><b>Rule H.5/5. The latch.</b> <b>A single write of any value</b> to <code>0x6000</code>&ndash;<code>0x7FFF</code> copies the running counter (all five registers) into the latched copy. <b>A processor write to a clock register reaches the running counter only, and a read returns the latched copy</b>, so a write followed immediately by a read returns the <em>old</em> value, not the one just written.</div>' +
    '<div class="gbemu-example"><b>Example.</b> Gate open, selector <code>0x08</code>, the latched seconds reading 10. Write 30 to <code>0xA000</code>: a read of <code>0xA000</code> still returns 10. Write <code>0x5A</code> to <code>0x6000</code>: the read now returns 30 (assuming no clock second has passed). <b>The discriminator, if you build your own:</b> after the first latch, write a single arbitrary byte to the latch region and <b>the read-back must change</b>. If your implementation needs a <code>0</code>-then-<code>1</code> sequence, that write changes nothing and you will print the same group fifty-two times.</div>' +
    '<div class="gbemu-why"><b>Why. The latch, and this is the one that refutes every reference.</b> Every published rule says writing <code>0x00</code> then <code>0x01</code> to <code>0x6000</code>&ndash;<code>0x7FFF</code> copies the running counter into the readable registers. Section 5 carries the full argument from <code>cpp/latch-rtc-test</code>, which writes one random byte to the latch region 52 times and never writes <code>0x00</code> or <code>0x01</code> again after its opening pair, yet the declared reference prints a different group every time. <b>CARTRIDGE-DECLARED.</b> The two halves of the rule follow and neither is a choice. A core that writes both copies together returns the new value at once: its read-back can never lag, and that is wrong.</div>' +
    '<div class="gbemu-rule" id="gbr-H-5-6"><b>Rule H.5/6. On an MBC3 without a clock (types <code>11</code> to <code>13</code>)</b> our core keeps the five clock registers anyway, as plain storage behind the same selectors: with RAM enabled, selector <code>08</code>-<code>0C</code> reads the latched copy and a write goes to the counter (masked to the register&rsquo;s width), a latch write copies the counter to the latched copy, and the counter never advances. So such a cartridge reads back what it wrote, after a latch, and zero before any write; it does not read <code>0xFF</code> there, and its writes do not reach RAM.</div>' +
    '<div class="gbemu-why"><b>Why.</b> Read from our source (the selector test does not look at the cartridge type; only the counting does).</div>' +
    '<div class="gbemu-rule" id="gbr-H-5-7"><b>Rule H.5/7. Before the first latch.</b> At power-on both copies, the running counter and the latched copy, hold 0 in all five registers (Rule H.2/6: every mapper register starts at 0), so a read before any latch write returns 0 from each clock register, whatever the counter has done since. The one exception is a clock the host restores with the battery save: our core exposes the whole clock block (latched copy, running counter, the latch register&rsquo;s last write and the sub-second count) for the host to keep beside cartridge RAM, and a restored block brings its latched copy with it.</div>' +
    '<div class="gbemu-why"><b>Why.</b> MECHANISM, read from our source (<code>gb_rtc_ptr</code>).</div>' +

    '<h4 class="gbemu-sub">H.6: MBC5</h4>' +
    '<p class="hw-readable">The simplest of the four and the one with no quirks to remember, which is exactly why it is worth stating what it does <em>not</em> do.</p>' +
    '<div class="gbemu-rule" id="gbr-H-6-1"><b>Rule H.6/1.</b> MBC5&rsquo;s registers:' +
    '<table class="gbemu-table"><thead><tr><th>Write address (hex)</th><th>Register</th><th>Width and masking (what is stored)</th></tr></thead><tbody>' +
    '<tr><td><code>0000&ndash;1FFF</code></td><td>RAM enable</td><td><code>(v &amp; 0x0F) == 0x0A</code></td></tr>' +
    '<tr><td><code>2000&ndash;2FFF</code></td><td>program bank, <b>low 8 bits</b></td><td>all 8 bits, stored unmasked</td></tr>' +
    '<tr><td><code>3000&ndash;3FFF</code></td><td>program bank, <b>bit 8</b></td><td><code>v &amp; 1</code></td></tr>' +
    '<tr><td><code>4000&ndash;5FFF</code></td><td>RAM bank</td><td><b>4 bits</b>, <code>v &amp; 0x0F</code>: 16 banks, 128&nbsp;KiB</td></tr>' +
    '<tr><td><code>6000&ndash;7FFF</code></td><td><b>nothing</b></td><td>Discarded. <b>MBC5 and MBC2 are the two mappers with an undecoded range inside <code>0x0000</code>&ndash;<code>0x7FFF</code></b>: Rule H.4/1 describes MBC2&rsquo;s <code>0x4000</code>&ndash;<code>0x7FFF</code> in the same words</td></tr>' +
    '</tbody></table></div>' +
    '<div class="gbemu-rule" id="gbr-H-6-2"><b>Rule H.6/2. The bank is a full 9 bits and there is NO zero-to-one correction.</b> <code>bank = (bit8 &lt;&lt; 8) | low8</code>, then masked by the cartridge. <b>Bank 0 is genuinely mappable into <code>0x4000</code>&ndash;<code>0x7FFF</code></b>, so the low window and the high window can show the same 16&nbsp;KiB.</div>' +
    '<div class="gbemu-example"><b>Example.</b> low8 = 0 and bit 8 = 0: the high window shows bank 0. low8 = <code>0x05</code> and bit 8 = 1: bank <code>0x105</code> on an 8&nbsp;MiB cartridge (512 banks, mask <code>0x1FF</code>); on a 2&nbsp;MiB cartridge (mask <code>0x7F</code>) <code>0x105</code> &amp; <code>0x7F</code> = bank 5.</div>' +
    '<div class="gbemu-why"><b>Why.</b> Carrying MBC1&rsquo;s correction over is the single commonest MBC5 error and it costs you bank 0 and nothing else, which is why it survives so long undetected: almost nothing maps bank 0 high on purpose, and the one Mooneye row that does is the one you fail.</div>' +
    '<div class="gbemu-rule" id="gbr-H-6-3"><b>Rule H.6/3. Rumble: the motor is modelled, the bank bit is not stripped.</b> Types <code>1C</code>&ndash;<code>1E</code> declare a rumble motor. Our core reports bit 3 of the RAM-bank register as the motor (appendix <a href="#gbe-extra-hw">A.1.3</a>), and it does not strip the bit: it uses all four bits as the RAM bank (Rule H.6/1, then Rule H.2/4).</div>' +
    '<div class="gbemu-example"><b>Example.</b> Type <code>1E</code> with 32&nbsp;KiB of RAM (4 banks): a write of <code>0x09</code> to <code>4000</code> turns the motor on and selects RAM bank 9 &amp; 3 = 1. With up to 64&nbsp;KiB (8 banks, mask 7) the mask always removes bit 3; only a rumble cartridge with more than 64&nbsp;KiB would see bit 3 in its RAM bank.</div>' +
    '<div class="gbemu-why"><b>Why.</b> On real hardware bit 3 of the RAM-bank register drives the motor rather than selecting a bank. <b>NOT ESTABLISHED and named rather than discovered:</b> a rumble cartridge with more than 64&nbsp;KiB of RAM would bank wrongly here. None is on the board. An implementer who wants it right masks bit 3 out of the RAM bank on those three types and routes it to the motor.</div>' +

    '<h4 class="gbemu-sub">H.7: No mapper, and the trap inside it</h4>' +
    '<div class="gbemu-rule" id="gbr-H-7-1"><b>Rule H.7/1.</b> With no mapper the low window is bank 0 and the high window is bank 1, permanently; <b>every write below <code>0x8000</code> is discarded</b>.</div>' +
    '<div class="gbemu-rule" id="gbr-H-7-2"><b>Rule H.7/2. The trap, stated because it is in this core as shipped.</b> Cartridge types <code>08</code> and <code>09</code> declare RAM with no mapper to enable it. Since the enable register is a mapper register and all mapper writes are discarded, <b>the gate can never open, so <code>0xA000</code>&ndash;<code>0xBFFF</code> reads <code>0xFF</code> for ever and every write is dropped.</b> The same applies to every unimplemented mapper type, which all fall to this path. A build that matches <em>this core</em> keeps the gate shut, as described here.</div>' +
    '<div class="gbemu-why"><b>Why.</b> <b>On hardware those two types wire the RAM directly with no gate.</b> <b>NOT ESTABLISHED against anything we hold</b> (no cartridge on the board uses either type) and an implementer should treat RAM as permanently enabled when the type is <code>08</code> or <code>09</code>. It is here so that a title which does use one fails in a way you can recognise instead of a way you cannot. <b>Which is the reference:</b> the advice is for a build that wants to be right on hardware; a build that wants to match this core follows Rule H.7/2. The two differ on no row we score.</div>' +

    '<h4 class="gbemu-sub">H.8: What each suite actually exercises</h4>' +
    '<p class="hw-readable">Half of this appendix is caught by nothing you would notice, so here is which cartridge sees which mistake. <b>All of these are stage 2 in the ladder of G.4</b>, and they are cheap rows: no picture processor beyond a background layer, no sound, no sub-instruction timing.</p>' +
    '<table class="gbemu-table"><thead><tr><th>Rows (board rows, counted)</th><th>What it reaches</th><th>What it will not catch</th></tr></thead><tbody>' +
    '<tr><td><b>Mooneye <code>mbc1</code></b><br>13 rows</td><td>The whole of H.3 and it is thorough: the register widths, the zero-to-one correction and <em>where</em> it sits in the order, the bank hole, both modes, the low-window remap at several program sizes, and the RAM-bank masking against a cartridge with one bank</td><td><b>Nothing in MBC1 is outside it: the multicart wiring included.</b> <code>emulator-only/mbc1</code> holds thirteen cartridges and reaches thirteen only <em>with</em> <code>multicart_rom_8Mb</code>, without it the directory is twelve. That cartridge is on our board, and it passes. This is the most complete mapper suite on the board, it <em>does</em> cover the multicart wiring, and <b>if all 13 pass, H.3 is right: detector included</b>. The detector remains a content heuristic with an acknowledged false-positive mode; what it is not is unscored</td></tr>' +
    '<tr><td><b>Mooneye <code>mbc2</code></b><br>7 rows</td><td>The address-bit-8 selector in both senses, the 4-bit bank register, the zero-to-one correction, and <b>the nibble RAM: the mirroring, the discarded upper nibble on write and the <code>0xF0</code> on read</b></td><td>Nothing in MBC2 is outside it</td></tr>' +
    '<tr><td><b>Mooneye <code>mbc5</code></b><br>8 rows</td><td>The 9-bit bank across both registers, <b>the absence of the zero-to-one correction</b>, and the 4-bit RAM bank</td><td><b>Rumble.</b> No row on the board drives the motor bit, so H.6&rsquo;s gap is invisible here</td></tr>' +
    '<tr><td><b>cpp</b><br>3 mapper rows</td><td>MBC3 specifically: <b>the width of the RAM/clock gate</b>, <b>the invalid selector returning <code>0xFF</code></b>, and <b>the single-write latch</b>. That last one declares its answer as 640 nibbles of hex rather than a picture, which is why it can refute a rule the whole literature states</td><td>The counter itself: it latches and reads, it does not run for long</td></tr>' +
    '<tr><td><b>ax6 <code>rtc3test</code></b><br>3 rows</td><td>The clock as a machine: <b>register widths, the exact-transition carry rule, out-of-range values counting within their own field, the 9-bit day counter, the sticky carry and the halt bit</b>. Up to 20 seconds of emulated time each, so they are among the slowest rows on the board</td><td>Banking. These are pure clock rows and will pass on a cartridge whose program banking is broken</td></tr>' +
    '<tr><td><b>Everything else</b><br>none</td><td>Commercial titles, which exercise MBC1, MBC3 and MBC5 constantly and <b>report nothing</b></td><td><b>This is the point of the appendix.</b> A wrong bank is not an error; it is data. Run the 34 rows before you conclude a title has a picture bug</td></tr>' +
    '</tbody></table>' +

    '<h4 class="gbemu-sub">H.9: What this appendix does not pin</h4>' +
    '<ul class="gbemu-bullets">' +
    '<li><b>H.10&rsquo;s chips are specified at the level of their decode</b>, each with its label in that table; no board row covers any of them.</li>' +
    '<li><b>The clocks keep real time across a save, and the host does the counting of time away</b> (Rule H.9/1). The ax6 rows still pass because they set the clock themselves and measure it inside one run.</li>' +
    '<li><b>The battery flag reaches nothing inside this core.</b> It is parsed and exported for the shell to decide whether to persist the RAM; the mapper behaves identically with and without it.</li>' +
    '<li><b>The MBC3 gate asymmetry in H.5</b>, and <b>the rumble bit in H.6</b>, and <b>the ungated RAM of types <code>08</code>/<code>09</code> in H.7</b>. All three are NOT ESTABLISHED, all three are unreached by every cartridge on the board, and all three are stated with what would settle them.</li>' +
    '<li><b>The multicart detector is a content heuristic</b> (H.3), <b>but being a heuristic and being unscored are two different properties, and this one is scored.</b> <code>mbc1/multicart_rom_8Mb</code> scores it, is one of the thirteen <code>mbc1</code> rows this page reports, and passes. What this appendix does not pin is the heuristic itself: it stays a content test, with its false-positive falsifier named in H.3.</li>' +
    '</ul>' +
    '<div class="gbemu-rule" id="gbr-H-9-1"><b>Rule H.9/1. The time away.</b> The MBC3 clock is a record the core exposes (the counter, the latched copy and the sub-second count) for the host to store beside the battery RAM, and the host advances it by the time since the save; the core does not. The HuC3 and TAMA5 clocks live inside the battery RAM itself, and the core advances them on request by a whole number of seconds away (a request of 0 or fewer seconds does nothing):' +
    '<ul class="gbemu-bullets">' +
    '<li><b>HuC3</b> adds the whole minutes (seconds &divide; 60, rounded down) to its minute counter, carrying into the day counter at 1,440 (Rule H.10/5), and keeps the remainder: the leftover seconds (seconds mod 60) are added to the sub-minute count, which carries one more minute if it reaches a whole minute.</li>' +
    '<li><b>TAMA5</b> steps its calendar one second at a time (Rule H.10/24) while its clock runs, at most 400 days per request; a stopped TAMA5 clock is not advanced.</li>' +
    '</ul></div>' +
    '<div class="gbemu-example"><b>Example.</b> HuC3 with its minute counter at 1,400 and an empty sub-minute count, advanced by 3,725 seconds: 62 whole minutes give 1,462, which carries one day and leaves 22; the 5 leftover seconds go into the sub-minute count. A TAMA5 request of 500 days steps 400 days (34,560,000 seconds).</div>' +
    '<div class="gbemu-why"><b>Why.</b> The order of the HuC3 steps and the treatment of the leftover seconds are read from our source (<code>gb_clock_advance</code>).</div>' +

    '<h4 class="gbemu-sub">H.10: The other licensed chips, as our core decodes them</h4>' +
    '<p class="hw-readable">Each is identified as Rule H.1/5 says (MMM01 and M161 by Rules H.10/11 and H.10/14), and each is one rule in our source with its own off switch. Labels are per chip, in the table below. The cartridge&rsquo;s peripherals (tilt, camera image, clock) are declared by the core to the host, which draws a control only for what the loaded cartridge has. All of the register detail below is read from our source; none of it is scored (H.9).</p>' +
    '<p class="hw-readable"><b>The Game Boy Printer.</b> Not a cartridge chip but a second device on the link cable. Our core answers a game&rsquo;s printer packets as a real printer does (the reply byte, the status byte, the packed picture data, the 8 KiB picture memory) and prints at a real printer&rsquo;s pace, about 14 seconds for a Game Boy Camera picture, so a game&rsquo;s own waits and its error messages behave as on the console. Its replies were checked reply for reply against recordings of a real printer from three games. The printer stays silent until a game sends it a packet, so a game that looks for a second Game Boy on the cable still finds none. Appendix <a href="#gbe-printer">A.1.2</a> gives it in full.</p>' +
    '<table class="gbemu-table"><thead><tr><th>Chip (type byte)</th><th>Rules</th><th>Label</th></tr></thead><tbody>' +
    '<tr><td><b>HuC1</b> (<code>FF</code>)</td><td>H.10/1</td><td>MECHANISM (the published chip description)</td></tr>' +
    '<tr><td><b>HuC3</b> (<code>FE</code>)</td><td>H.10/2 to H.10/5</td><td>MECHANISM. FITTED: every extended command answers 1. The tone generator&rsquo;s trigger is modelled and its sound is FITTED (appendix <a href="#gbe-extra-hw">A.1.3</a>). Not modelled: the alarm update on a time set, and command 2, whose purpose is undocumented</td></tr>' +
    '<tr><td><b>MBC7</b> (<code>22</code>)</td><td>H.10/6 to H.10/10</td><td>MECHANISM. Programming is self-timed (the self-timing is MECHANISM; the 2&nbsp;ms is FITTED)</td></tr>' +
    '<tr><td><b>MMM01</b></td><td>H.10/11 to H.10/13</td><td>MECHANISM. FITTED: the <code>11</code> footer arm</td></tr>' +
    '<tr><td><b>M161</b></td><td>H.10/14, H.10/15</td><td>MECHANISM for the decode; FITTED for the identification (the board carries no mark of its own)</td></tr>' +
    '<tr><td><b>Pocket Camera</b> (<code>FC</code>)</td><td>H.10/16 to H.10/19</td><td>MECHANISM. FITTED: brightness unity at exposure <code>0x1000</code>; writing 0 stops a capture with no image. Not modelled: gain and level control</td></tr>' +
    '<tr><td><b>TAMA5</b> (<code>FD</code>)</td><td>H.10/20 to H.10/24</td><td>SOURCE-READ from a single reference implementation (no published description exists). The clock&rsquo;s register widths are derived from its digits; a page read returns the page its number names</td></tr>' +
    '<tr><td><b>MBC6</b> (<code>20</code>)</td><td>H.10/25, H.10/26</td><td>MECHANISM. FITTED: the unlock addresses matched on the window offset; banks 2 and 3 at power-on</td></tr>' +
    '</tbody></table>' +

    '<p class="gbemu-key"><b>HuC1</b> (<code>FF</code>)</p>' +
    '<div class="gbemu-rule" id="gbr-H-10-1"><b>Rule H.10/1.</b> HuC1 decodes:' +
    '<table class="gbemu-table"><thead><tr><th>Address (hex)</th><th>Access</th><th>Effect</th></tr></thead><tbody>' +
    '<tr><td><code>0000</code>&ndash;<code>1FFF</code></td><td>write</td><td>A value whose low nibble is <code>0E</code> selects the infrared register; any other value selects RAM again. There is no RAM enable: RAM is always on, with no disable</td></tr>' +
    '<tr><td><code>2000</code>&ndash;<code>3FFF</code></td><td>write</td><td>switchable program bank, 6 bits (<code>v &amp; 0x3F</code>), bank 0 not remapped (no zero-to-one correction), masked by the cartridge</td></tr>' +
    '<tr><td><code>4000</code>&ndash;<code>5FFF</code></td><td>write</td><td>RAM bank, 2 bits (<code>v &amp; 3</code>), then Rule H.2/4</td></tr>' +
    '<tr><td><code>6000</code>&ndash;<code>7FFF</code></td><td>write</td><td>no effect</td></tr>' +
    '<tr><td><code>A000</code>&ndash;<code>BFFF</code>, RAM selected</td><td>read, write</td><td>cartridge RAM (<code>0xFF</code> on a read with no RAM)</td></tr>' +
    '<tr><td><code>A000</code>&ndash;<code>BFFF</code>, infrared selected</td><td>read</td><td><code>0xC0</code> (no light; <code>0xC1</code> when a linked partner&rsquo;s light arrives, appendix <a href="#gbe-extra-hw">A.1.3</a>)</td></tr>' +
    '<tr><td><code>A000</code>&ndash;<code>BFFF</code>, infrared selected</td><td>write</td><td>bit 0 written is the LED</td></tr>' +
    '</tbody></table></div>' +
    '<div class="gbemu-example"><b>Example.</b> A write of <code>0x0E</code> or <code>0x1E</code> to <code>0x0000</code> selects the infrared register; a following write of <code>0x0A</code> selects RAM again (it is not a RAM enable).</div>' +

    '<p class="gbemu-key"><b>HuC3</b> (<code>FE</code>)</p>' +
    '<div class="gbemu-rule" id="gbr-H-10-2"><b>Rule H.10/2.</b> HuC3&rsquo;s mapper writes: <code>0000</code>&ndash;<code>1FFF</code> sets the <b>mode register</b> (the low nibble of <code>v</code>), which chooses what <code>A000</code>&ndash;<code>BFFF</code> is (Rule H.10/3); <code>2000</code>&ndash;<code>3FFF</code> the program bank, 7 bits (<code>v &amp; 0x7F</code>, bank 0 may be mapped), masked by the cartridge; <code>4000</code>&ndash;<code>5FFF</code> the RAM bank, 2 bits (<code>v &amp; 3</code>), then Rule H.2/4; <code>6000</code>&ndash;<code>7FFF</code> no effect.</div>' +
    '<div class="gbemu-rule" id="gbr-H-10-3"><b>Rule H.10/3.</b> The mode register decides the RAM window:' +
    '<table class="gbemu-table"><thead><tr><th>Mode (hex)</th><th>A read of <code>A000</code>&ndash;<code>BFFF</code></th><th>A write to <code>A000</code>&ndash;<code>BFFF</code></th></tr></thead><tbody>' +
    '<tr><td><code>0</code></td><td>RAM (<code>0xFF</code> with no RAM)</td><td>ignored (read only)</td></tr>' +
    '<tr><td><code>A</code></td><td>RAM (<code>0xFF</code> with no RAM)</td><td>RAM</td></tr>' +
    '<tr><td><code>B</code></td><td><code>0xFF</code></td><td>the <b>mailbox</b>: bit 7 is not connected; bits 4 to 6 the command, bits 0 to 3 the argument</td></tr>' +
    '<tr><td><code>C</code></td><td>the <b>response</b>: <code>0x80 OR (mailbox command bits 4-6) OR result nibble</code></td><td>ignored</td></tr>' +
    '<tr><td><code>D</code></td><td>the <b>semaphore</b>: <code>0xFF</code> (always ready)</td><td>a write with bit 0 clear executes the mailbox command (Rule H.10/4); bit 0 set does nothing</td></tr>' +
    '<tr><td><code>E</code></td><td>infrared: <code>0xC0</code> (<code>0xC1</code> when a linked partner&rsquo;s light arrives)</td><td>bit 0 is the LED</td></tr>' +
    '<tr><td>any other</td><td><code>0xFF</code></td><td>ignored</td></tr>' +
    '</tbody></table></div>' +
    '<div class="gbemu-rule" id="gbr-H-10-4"><b>Rule H.10/4.</b> Behind the mailbox sit 256 nibbles of controller memory with an auto-incrementing 8-bit address. Executing a command (a mode-<code>D</code> write with bit 0 clear) does, by command:' +
    '<table class="gbemu-table"><thead><tr><th>Command (mailbox bits 4-6)</th><th>Effect</th><th>Result nibble</th></tr></thead><tbody>' +
    '<tr><td>1</td><td>read the nibble at the address into the result, then add 1 to the address</td><td>that nibble</td></tr>' +
    '<tr><td>3</td><td>write the argument at the address, then add 1 to the address</td><td>unchanged</td></tr>' +
    '<tr><td>4</td><td>set the address&rsquo;s low nibble to the argument</td><td>unchanged</td></tr>' +
    '<tr><td>5</td><td>set the address&rsquo;s high nibble to the argument</td><td>unchanged</td></tr>' +
    '<tr><td>6</td><td>extended, chosen by the argument: 0 copies the time nibbles <code>10</code>-<code>15</code> to <code>00</code>-<code>05</code> (time to memory); 1 copies the other way (memory to time); 2 status (no memory effect); <code>E</code> the tone trigger (appendix <a href="#gbe-extra-hw">A.1.3</a>); any other argument, no memory effect</td><td>1, for every extended command</td></tr>' +
    '<tr><td>0, 2, 7</td><td>nothing</td><td>unchanged</td></tr>' +
    '</tbody></table></div>' +
    '<div class="gbemu-example"><b>Example.</b> To read the nibble at <code>0x10</code>: write <code>0x0B</code> to <code>0x0000</code> (mode B), <code>0x40</code> to <code>0xA000</code> (command 4, argument 0); write <code>0x0D</code> to <code>0x0000</code> and <code>0x00</code> to <code>0xA000</code> (execute: address low nibble 0). Repeat with mailbox <code>0x51</code> (command 5, argument 1: address <code>0x10</code>), then with <code>0x10</code> (command 1). If the nibble at <code>0x10</code> is 7, the result is 7 and the address is now <code>0x11</code>; in mode C (<code>0x0C</code> to <code>0x0000</code>) a read of <code>0xA000</code> returns <code>0x80 | 0x10 | 7</code> = <code>0x97</code>.</div>' +
    '<div class="gbemu-rule" id="gbr-H-10-5"><b>Rule H.10/5. The HuC3 clock.</b> The minute counter is the three nibbles at <code>0x10</code> to <code>0x12</code>, least significant first (12 bits, rolling at 1,440 into the day counter); the day counter is the three at <code>0x13</code> to <code>0x15</code>, least significant first, 12 bits, wrapping from 4,095 to 0. The minute counter adds 1 every 60 clock seconds of emulated time, on the clock-second scale of Rule H.5/4, and is advanced by the time away (Rule H.9/1). A time set does not update the alarm.</div>' +
    '<div class="gbemu-example"><b>Example.</b> Nibbles <code>0x10</code>&ndash;<code>0x12</code> = <code>F</code>, <code>9</code>, <code>5</code> hold <code>0x59F</code> = 1,439 minutes. One minute later they read <code>0</code>, <code>0</code>, <code>0</code> and the day counter has added 1.</div>' +

    '<p class="gbemu-key"><b>MBC7</b> (<code>22</code>)</p>' +
    '<div class="gbemu-rule" id="gbr-H-10-6"><b>Rule H.10/6.</b> MBC7&rsquo;s mapper writes: <code>0000</code>-<code>1FFF</code> is the first RAM enable (low nibble <code>A</code>, as MBC1); <code>2000</code>-<code>3FFF</code> is the switchable bank, all 8 bits, masked to the image&rsquo;s bank count, with bank 0 not remapped (an MBC5-style switchable bank); <code>4000</code>-<code>5FFF</code> is the second enable, which only <code>0x40</code> opens (the whole byte); <code>6000</code>-<code>7FFF</code> has no effect. Two RAM enables (<code>0x0A</code>, then <code>0x40</code>): both must be open, the first with <code>0x0A</code> in the low nibble and the second with <code>0x40</code>, in either order, for the accelerometer and the EEPROM to answer in <code>A000</code>-<code>AFFF</code> (Rule H.10/7). With either enable shut, all of <code>A000</code>-<code>BFFF</code> reads <code>0xFF</code> and ignores writes; <code>B000</code> up always reads <code>0xFF</code>.</div>' +
    '<div class="gbemu-rule" id="gbr-H-10-7"><b>Rule H.10/7.</b> The accelerometer and EEPROM block at <code>A000</code>-<code>AFFF</code> (both enables open) is selected by address bits 4 to 7, so each register repeats every 16 bytes (&ldquo;<code>2_</code>&rdquo; means <code>A020</code>-<code>A02F</code>):' +
    '<table class="gbemu-table"><thead><tr><th>Offset (address bits 4-7)</th><th>Read</th><th>Write</th></tr></thead><tbody>' +
    '<tr><td><code>0_</code></td><td><code>0xFF</code></td><td><code>0x55</code> erases the latch (Rule H.10/8)</td></tr>' +
    '<tr><td><code>1_</code></td><td><code>0xFF</code></td><td><code>0xAA</code> latches, when armed (Rule H.10/8)</td></tr>' +
    '<tr><td><code>2_</code>, <code>3_</code></td><td>x low, x high</td><td>ignored</td></tr>' +
    '<tr><td><code>4_</code>, <code>5_</code></td><td>y low, y high</td><td>ignored</td></tr>' +
    '<tr><td><code>6_</code></td><td><code>0x00</code></td><td>ignored</td></tr>' +
    '<tr><td><code>8_</code></td><td>the EEPROM pin byte, all four pins (Rule H.10/9)</td><td>the EEPROM pin byte: chip select, clock and data in</td></tr>' +
    '<tr><td>every other</td><td><code>0xFF</code></td><td>ignored</td></tr>' +
    '</tbody></table></div>' +
    '<div class="gbemu-rule" id="gbr-H-10-8"><b>Rule H.10/8. The accelerometer latch.</b>' +
    '<ol class="gbemu-steps">' +
    '<li>A write of <code>0x55</code> at offset <code>0_</code> erases the latch to <code>0x8000</code> on both axes and arms it.</li>' +
    '<li>A write of <code>0xAA</code> at offset <code>1_</code>, when armed, latches both axes from the tilt and disarms. When not armed it does nothing: it does not re-latch without an erase.</li>' +
    '</ol>' +
    'The axis value is <code>0x81D0 + 0x70</code> per g, clamped to 16 bits, centred at <code>0x81D0</code>. Tilt: x above 0 is tilted left, y above 0 toward the top. The tilt comes from the host; with none, both axes latch <code>0x81D0</code>. At power-on both axis latches hold <code>0x8000</code> until the first latch.</div>' +
    '<div class="gbemu-example"><b>Example.</b> Host tilt 0.5&nbsp;g on x (tilted left) and 0 on y: write <code>0x55</code> to <code>0xA000</code>, then <code>0xAA</code> to <code>0xA010</code>. x = <code>0x81D0</code> + <code>0x38</code> = <code>0x8208</code>, so <code>0xA020</code> reads <code>0x08</code> and <code>0xA030</code> reads <code>0x82</code>; y reads <code>0xD0</code>, <code>0x81</code>. A second <code>0xAA</code> without a new <code>0x55</code> leaves both values.</div>' +
    '<div class="gbemu-rule" id="gbr-H-10-9"><b>Rule H.10/9. The serial EEPROM.</b> 256 bytes: 128 words of 16 bits. <b>The pin byte at <code>8_</code></b>: bit 7 chip select, bit 6 clock, bit 1 data in, bit 0 data out; a write sets the first three, a read returns all four (the first three as last written). A command is clocked on rising clock edges (a write with bit 6 set after one with bit 6 clear) with chip select high:' +
    '<ol class="gbemu-steps">' +
    '<li>While waiting for a command, clocked 0 bits are ignored; the first rising edge with data in = 1 is the start bit.</li>' +
    '<li>The next 10 rising edges take 10 bits, the 2-bit opcode first and then 8 address bits, of which the low 7 are the word address.</li>' +
    '<li>The opcode then acts, by this table:' +
    '<table class="gbemu-table"><thead><tr><th>Opcode (2 bits)</th><th>Command</th></tr></thead><tbody>' +
    '<tr><td><code>10</code></td><td>read: data out goes to 0 for the dummy bit on the same rising edge that takes the last of the ten command bits; each following rising edge puts out one data bit, most significant first, and after 16 the next word follows (sequential read: the word address adds 1, wrapping within the 128 words)</td></tr>' +
    '<tr><td><code>01</code></td><td>write: 16 data bits follow, most significant first</td></tr>' +
    '<tr><td><code>11</code></td><td>erase one word to <code>0xFFFF</code></td></tr>' +
    '<tr><td><code>00</code></td><td>extended, chosen by the top two of the 8 address bits (bits 7 and 6, the two bits sent straight after the opcode; the other six are ignored): <code>11</code> write enable, <code>00</code> write disable, <code>10</code> erase all, <code>01</code> write all (16 data bits follow)</td></tr>' +
    '</tbody></table></li>' +
    '<li>Chip select low ends any command and returns to step 1.</li>' +
    '</ol></div>' +
    '<div class="gbemu-example"><b>Example.</b> One bit is clocked by two writes to <code>0xA080</code>: <code>0x82</code> (chip select 1, clock 0, data in 1) and then <code>0xC2</code> (clock 1): a rising edge with data in = 1. To read word 5: clock in 1 (start), then 1, 0 (opcode <code>10</code>), then <code>0000 0101</code>. On the 11th rising edge (the last address bit) data out goes to 0, the dummy bit. Rising edges 12 to 27 put out bits 15 to 0 of word 5; edge 28 puts out bit 15 of word 6.</div>' +
    '<div class="gbemu-rule" id="gbr-H-10-10"><b>Rule H.10/10. Busy, ready and power-on.</b> Writes and erases (write, erase, erase all, write all) need write enable, which is clear at power-on; without it they change nothing. With it, the chip becomes busy: data out reads 0 for 2&nbsp;ms of emulated time, 8,389 T-cycles (2&nbsp;ms of the master clock, rounded up), and then 1, and no command is taken meanwhile. The busy time starts on the rising clock edge that takes the command&rsquo;s last bit (the 16th data bit of a write or write all; the 10th command bit of an erase or erase all). With chip select low, data out reads 1 when ready and 0 while busy. With chip select high and no command running, data out keeps the level it last had (1 at power-on, after chip select low, and when a busy time ends). <b>At power-on the EEPROM holds 0 in every word</b>, like any cartridge memory (section 3), not the erased <code>0xFFFF</code>, unless a save is loaded.</div>' +
    '<div class="gbemu-example"><b>Example.</b> After write enable, a write command&rsquo;s 16th data bit is taken on a rising edge at T-cycle t (counted on the master clock); data out reads 0 until t + 8,389 and 1 from then on, and clock edges in between start nothing.</div>' +
    '<div class="gbemu-why"><b>Why.</b> The busy count runs on the same scale as the clock of Rule H.5/4: the processor&rsquo;s T-cycles at single speed, and on a Colour in double speed twice as many of the processor&rsquo;s T-cycles (it is counted in wall time). Read from our source.</div>' +

    '<p class="gbemu-key"><b>MMM01</b></p>' +
    '<div class="gbemu-rule" id="gbr-H-10-11"><b>Rule H.10/11. Identification.</b> MMM01 is recognised by a second header in the last 32&nbsp;KiB of the image (with the logo block and type <code>0B</code> to <code>0D</code>, or <code>11</code>). Exactly, all four must hold:' +
    '<ol class="gbemu-steps">' +
    '<li>The image is at least 64&nbsp;KiB.</li>' +
    '<li>The footer header sits at the start of the last 32&nbsp;KiB: offset = length rounded down to a multiple of 32&nbsp;KiB, less 32&nbsp;KiB.</li>' +
    '<li>Its 48 bytes at footer + <code>0x104</code> equal the image&rsquo;s own 48 bytes at <code>0x104</code> (the same rule as M161, Rule H.10/14: a comparison with the cartridge&rsquo;s first header, so this page needs to print no logo, and no other check is made on the bytes).</li>' +
    '<li>Its byte at footer + <code>0x147</code> is <code>0B</code>, <code>0C</code>, <code>0D</code> or <code>11</code>.</li>' +
    '</ol>' +
    'The RAM size then comes from the footer&rsquo;s <code>0x149</code>, and <code>0D</code> means a battery.</div>' +
    '<div class="gbemu-example"><b>Example.</b> An image of <code>0x48000</code> bytes (288&nbsp;KiB): rounded down to 32&nbsp;KiB it is still <code>0x48000</code>, so the footer is at <code>0x40000</code>, and the bytes compared are <code>0x40104</code>&ndash;<code>0x40133</code> against <code>0x0104</code>&ndash;<code>0x0133</code>, with the type at <code>0x40147</code>.</div>' +
    '<div class="gbemu-rule" id="gbr-H-10-12"><b>Rule H.10/12. Writes and locks.</b> Every register starts at 0. Until the mapping is locked, the low window shows bank <code>rom_banks &minus; 2</code> and the high window bank <code>rom_banks &minus; 1</code>, where <code>rom_banks</code> is the image&rsquo;s length in 16&nbsp;KiB banks rounded up to a power of two (no header&rsquo;s <code>0x0148</code> is read for it). For an image whose length is a power of two those are its last 32&nbsp;KiB, the footer of Rule H.10/11. For any other length they lie past the image&rsquo;s end and read <code>0xFF</code> (Rule H.2/4): the 288&nbsp;KiB image of Rule H.10/11&rsquo;s example has <code>rom_banks</code> = 32, so banks 30 and 31, not its footer at banks 16 and 17. Read from our source. &ldquo;While unlocked&rdquo; below means before the write that locks the mapping; those bits are only writable then.' +
    '<table class="gbemu-table"><thead><tr><th>Write address (hex)</th><th>Any time</th><th>Only while unlocked</th></tr></thead><tbody>' +
    '<tr><td><code>0000</code>-<code>1FFF</code></td><td>low nibble <code>A</code> opens RAM (Rule H.2/2)</td><td>bits 4 and 5 lock RAM-bank bits 0 and 1; bit 6 locks the mapping for good</td></tr>' +
    '<tr><td><code>2000</code>-<code>3FFF</code></td><td>the low five bits are the program bank, but only the bits the mask leaves unlocked change; locked bits keep their value</td><td>bits 5 and 6 are the middle program bits</td></tr>' +
    '<tr><td><code>4000</code>-<code>5FFF</code></td><td>bits 0 and 1 the RAM bank (subject to the RAM lock, as above)</td><td>bits 2 and 3 the high RAM bits, 4 and 5 the high program bits, 6 write-protects the mode bit</td></tr>' +
    '<tr><td><code>6000</code>-<code>7FFF</code></td><td>bit 0 the mode (unless protected)</td><td>bits 2 to 5 lock program-bank bits 1 to 4 (bit 0 always stays writable); bit 6 is the multiplex</td></tr>' +
    '</tbody></table>' +
    'A lock mask acts from the write that sets it, before and after the mapping is locked.</div>' +
    '<div class="gbemu-rule" id="gbr-H-10-13"><b>Rule H.10/13. Banks once locked.</b> The two windows differ:' +
    '<ol class="gbemu-steps">' +
    '<li>The low window (<code>0000</code>-<code>3FFF</code>) takes only the <em>locked</em> bits of the low five program bits (the changeable ones read as 0 there).</li>' +
    '<li>The high window (<code>4000</code>-<code>7FFF</code>) takes all five; if the changeable bits are all zero, it ORs in 1, using the mask as it stands now.</li>' +
    '<li>Both add the middle bits at bit 5 and the high program bits at bit 7, then are masked by the cartridge. With the multiplex set, the RAM-bank bits take the place of the middle bits: in the high window all of them; in the low window all of them with the mode bit set, the locked ones without.</li>' +
    '<li>The RAM bank, then Rule H.2/4. The mode bit (<code>6000</code> bit 0) matters in two places only. With the multiplex clear, the RAM bank is (high RAM bits &times; 4) + the low two RAM bits, all of them when the mode bit is set and only the locked ones when it is clear. With the multiplex set, the RAM bank is (high RAM bits &times; 4) + the program bank&rsquo;s middle bits, and the low window&rsquo;s middle bits take the RAM bits (step 3).</li>' +
    '</ol></div>' +
    '<div class="gbemu-example"><b>Example.</b> A 512&nbsp;KiB image (32 banks). While unlocked, write <code>0x10</code> to <code>0x2000</code> (program bits <code>0x10</code>, middle bits 0), then <code>0x3C</code> to <code>0x6000</code> (bits 2 to 5 set: program-bank bits 1 to 4 locked; mode 0, multiplex clear), then lock with <code>0x40</code> to <code>0x0000</code>. The low window takes the locked bits of <code>0x10</code>: bank <code>0x10</code>. The changeable bit (bit 0) is 0, so the high window shows <code>0x10 | 1</code> = <code>0x11</code>. A later write of <code>0x13</code> to <code>0x2000</code> changes only bit 0: the low five become <code>0x11</code>, the low window stays <code>0x10</code>, and the high window shows <code>0x11</code> with no OR needed. Had <code>0x10</code> been written after the mask, it would have stored 0, since bit 4 was already locked.</div>' +

    '<p class="gbemu-key"><b>M161</b></p>' +
    '<div class="gbemu-rule" id="gbr-H-10-14"><b>Rule H.10/14. Identification.</b> M161 is recognised from type <code>10</code> on an image of 128 to 256&nbsp;KiB with at least three later 32&nbsp;KiB slots repeating the logo block with type <code>00</code>. Exactly: for each later slot at offset 32&nbsp;KiB &times; k (k = 1, 2, &hellip;, while the slot&rsquo;s first <code>0x150</code> bytes lie inside the image), the slot counts when the 48 bytes at slot + <code>0x104</code> equal the image&rsquo;s own 48 bytes at <code>0x104</code> (a comparison with the cartridge&rsquo;s first header, not with Nintendo&rsquo;s logo, so a header whose logo area is all zero matches its zero copies) and the slot&rsquo;s byte at <code>0x147</code> is <code>00</code>; three or more such slots make it M161 (no RAM, no clock, no battery, 16 banks of 16&nbsp;KiB).</div>' +
    '<div class="gbemu-rule" id="gbr-H-10-15"><b>Rule H.10/15. The latch.</b> A one-shot 3-bit latch selecting 32&nbsp;KiB banks (slots); slot 0 at power-on. The latch takes a write to any address from <code>0000</code> to <code>7FFF</code>, the first one only, and stores <code>v &amp; 7</code>; later writes are ignored until power-off. Slot s shows bank 2s in the low window and bank 2s + 1 in the high window.</div>' +
    '<div class="gbemu-example"><b>Example.</b> A 256&nbsp;KiB image with slots at <code>0x8000</code>, <code>0x10000</code>, &hellip; <code>0x38000</code> (k = 1 to 7); four of them repeat the logo with type <code>00</code>: M161. The game writes <code>0x03</code> to <code>0x2000</code>: slot 3, banks 6 and 7, image offsets <code>0x18000</code>&ndash;<code>0x1FFFF</code>. A later write of <code>0x01</code> changes nothing.</div>' +

    '<p class="gbemu-key"><b>Pocket Camera</b> (<code>FC</code>)</p>' +
    '<div class="gbemu-rule" id="gbr-H-10-16"><b>Rule H.10/16. Registers and RAM.</b>' +
    '<table class="gbemu-table"><thead><tr><th>Address (hex)</th><th>Effect</th></tr></thead><tbody>' +
    '<tr><td><code>0000</code>-<code>1FFF</code> write</td><td>the RAM enable (<code>0x0A</code> in the low nibble) gates RAM <em>writes only</em>: RAM reads, and register reads and writes while mapped, never need it</td></tr>' +
    '<tr><td><code>2000</code>-<code>3FFF</code> write</td><td>switchable bank <code>0x00</code> to <code>0x3F</code> (<code>v &amp; 0x3F</code>), masked by the cartridge</td></tr>' +
    '<tr><td><code>4000</code>-<code>5FFF</code> write</td><td>bit 4 maps the registers (set) or RAM (clear) into <code>A000</code>-<code>BFFF</code>; bits 0 to 3 set the RAM bank as well, either way (then Rule H.2/4)</td></tr>' +
    '<tr><td><code>A000</code>-<code>BFFF</code>, registers mapped</td><td>the registers, repeating every <code>0x80</code> (offset = address &amp; <code>0x7F</code>). A read at offset 0 returns register 0, and every other offset reads <code>0x00</code>. Writes to offsets 0 to <code>0x35</code> store the register</td></tr>' +
    '<tr><td><code>A000</code>-<code>BFFF</code>, RAM mapped</td><td>cartridge RAM; while a capture is busy, RAM reads <code>0x00</code> and ignores writes</td></tr>' +
    '</tbody></table>' +
    '<b>The camera registers in full</b> (offsets from <code>A000</code> with the registers mapped): register 0 stores only its low three bits; bit 0 is the busy bit, set by the write that starts a capture and cleared when the capture finishes or by writing it 0. Register 1: bit 7 is N and bits 5 and 6 are VH. Registers 2 and 3 are the exposure, high byte then low. Register 4: bits 4 to 6 select the edge ratio (0.5, 0.75, 1, 1.25, 2, 3, 4, 5 for 0 to 7), bit 3 inverts the picture and bit 7 is E3. <code>06</code> to <code>35</code> are the threshold matrix, 16 cells of 3 bytes, cell (x mod 4) + 4 &times; (y mod 4), each cell three ascending thresholds.</div>' +
    '<div class="gbemu-rule" id="gbr-H-10-17"><b>Rule H.10/17. A capture.</b>' +
    '<ol class="gbemu-steps">' +
    '<li>A write to register 0 with bit 0 set, while bit 0 is clear, starts a capture and sets busy. N and the exposure as they stand at this write fix its length: 32,446 machine cycles, plus 512 when N is clear, plus 16 times the exposure. The length is counted in single-speed machine cycles: on a Colour in double speed the cartridge&rsquo;s clock runs at the single-speed rate, so the capture lasts twice as many machine cycles.</li>' +
    '<li>Writing register 0 with bit 0 clear stops a capture with no image.</li>' +
    '<li>When the length has passed, the capture finishes: every other register (VH, E3, the ratio, invert, the matrix, and the exposure for the brightness) is read as it stands now, the picture is formed (Rule H.10/18) and written to RAM bank 0 from <code>0x0100</code>, 16 tiles across and 14 down, as ordinary 2-bit tiles, and busy clears.</li>' +
    '</ol></div>' +
    '<div class="gbemu-example"><b>Example.</b> Exposure <code>0x0100</code> (256) with N = 1: 32,446 + 16 &times; 256 = 36,542 single-speed machine cycles; with N = 0, 37,054.</div>' +
    '<div class="gbemu-rule" id="gbr-H-10-18"><b>Rule H.10/18. The picture, the order and the arithmetic, exactly.</b> For each pixel (128 by 112):' +
    '<ol class="gbemu-steps">' +
    '<li>Brightness, formed first for the pixel and for each neighbour the enhancement uses: sensor value &times; exposure / <code>0x1000</code> in whole numbers, rounded down, capped at 255, then inverted (255 minus it) if bit 3 of register 4 is set.</li>' +
    '<li>The edge mode, chosen by N, VH and E3 together: with N = 1, VH = 3, E3 = 0 the two-dimensional enhancement adds ratio &times; (4p &minus; the four neighbours) / 4; with N = 0, VH = 1, E3 = 0 the horizontal one adds ratio &times; (2p &minus; left &minus; right) / 4; with only E3 set (N = 0, VH = 0, E3 = 1) the output is 0; every other combination leaves the pixel as it is. Neighbours at the image edge repeat the edge pixel. The ratio is held as a quarter-step whole number (2, 3, 4, 5, 8, 12, 16, 20 for 0.5 to 5) and the sum divided by 4 rounding toward zero; the result is <b>not</b> clamped before the thresholds, so it may be below 0 or above 255.</li>' +
    '<li>The shade, from the pixel&rsquo;s matrix cell: 3 below the cell&rsquo;s first threshold, 2 below the second, 1 below the third, else 0.</li>' +
    '</ol></div>' +
    '<div class="gbemu-example"><b>Example.</b> Sensor value 128, exposure <code>0x0800</code>, no invert, no edge mode: brightness 128 &times; 2,048 / 4,096 = 64. With the cell&rsquo;s thresholds <code>0x40</code>, <code>0x80</code>, <code>0xC0</code>: 64 is not below the first (64), but is below the second (128), so the shade is 2.</div>' +
    '<div class="gbemu-rule" id="gbr-H-10-19"><b>Rule H.10/19. The sensor image</b> comes from the host (the site&rsquo;s camera control). With none supplied, our core captures a fixed test card of its own, 128 by 112, so a capture always writes a picture:' +
    '<ol class="gbemu-steps">' +
    '<li>A left-to-right ramp: column x has the value 32 + (x &times; 191 / 127), rounded down, from 32 to 223.</li>' +
    '<li>A dark disc (value 24) of radius 24 centred at column 44, row 56: the pixels whose squared distance from (44, 56) is <em>less than</em> 576 (the rim excluded).</li>' +
    '<li>A bright bar (value 232) over columns 88 to 111 and rows 20 to 91, drawn over the disc.</li>' +
    '</ol></div>' +
    '<div class="gbemu-example"><b>Example.</b> Column 0 reads 32 and column 127 reads 223; column 64 reads 32 + 12,224 / 127 = 32 + 96 = 128. Pixel (44, 80) is 24 rows from the centre: squared distance 576, not less than 576, so it is ramp (column 44: 32 + 66 = 98), not disc.</div>' +

    '<p class="gbemu-key"><b>TAMA5</b> (<code>FD</code>)</p>' +
    '<div class="gbemu-rule" id="gbr-H-10-20"><b>Rule H.10/20. The register map.</b> The chip listens at <code>A000</code> and <code>A001</code> only; mapper writes to <code>0000</code>-<code>7FFF</code> do nothing. A write to <code>A001</code> (any odd address) selects a register. A write to <code>A000</code> (an even address) stores the low nibble into the selected register 0 to 7 (selects 8 and up are ignored). Registers 0 and 1 are the bank, low and high nibble: of the 8 bits they form, the bank uses 5 (then masked by the cartridge). Registers 4 and 5 are the data nibbles (low, high); 6 and 7 the command and address: the address is (bit 0 of register 6 &times; 16) + register 7, the operation is register 6 shifted right once, and writing register 7 executes it. The cartridge has 32 bytes of RAM.</div>' +
    '<div class="gbemu-rule" id="gbr-H-10-21"><b>Rule H.10/21. The operations</b> (executed by a write of register 7):' +
    '<table class="gbemu-table"><thead><tr><th>Operation</th><th>Effect</th></tr></thead><tbody>' +
    '<tr><td>0</td><td>write the data byte (register 5 &times; 16 + register 4) to RAM at the address (32 bytes)</td></tr>' +
    '<tr><td>1</td><td>a RAM read (the read path of Rule H.10/22 returns the RAM byte at the address)</td></tr>' +
    '<tr><td>2</td><td>a clock command, by address: 0 stop, 1 start and clear seconds, 4 set minutes, 5 set hours from the data byte, <code>10</code> and <code>11</code> alarm off and on</td></tr>' +
    '<tr><td>4</td><td>write a clock page register: register 4 is the register number, register 5 the value, masked to its width (Rule H.10/23); the page comes from register 7 when it is even and at most 6: the page is register 7 halved, so 0 names the timer page (page 0), 2 the alarm page (page 1), 4 and 6 the two free pages (pages 2 and 3). An odd value, or 8 and up, writes nothing, and register numbers <code>D</code> and up are not written</td></tr>' +
    '</tbody></table></div>' +
    '<div class="gbemu-example"><b>Example.</b> Write <code>0x5A</code> to RAM address <code>0x13</code>: select register 4 (write 4 to <code>0xA001</code>) and write <code>0xA</code> to <code>0xA000</code>; select 5, write 5; select 6, write 1 (operation 0, address bit 4 set); select 7, write 3. The last write executes: address 1 &times; 16 + 3 = <code>0x13</code>, operation = 1 shifted right once = 0, data byte 5 &times; 16 + <code>0xA</code> = <code>0x5A</code>.</div>' +
    '<div class="gbemu-rule" id="gbr-H-10-22"><b>Rule H.10/22. Reads.</b> A read of an odd address reads <code>0xFF</code>. A read of <code>A000</code> returns <code>0xF0 | nibble</code> (the nibble with the upper bits high): with select <code>0C</code> the low nibble of the result and with <code>0D</code> the high nibble; any other select reads <code>0xF1</code>. The result is, by the operation in register 6: for operation 1 the RAM byte at the address; for operation 2 at addresses 6 and 7 one byte of minutes or hours, tens in the high nibble and units in the low (in 12-hour mode the hours tens nibble carries the PM bit), and at any other address the address itself; for operation 4 the selected page&rsquo;s register, the page taken from the odd numbers the same way (register 7 halved and rounded down, so 1 reads the timer page, 3 the alarm page, 5 and 7 the free pages), and a register number above <code>D</code> reads 0; for any other operation, 0.</div>' +
    '<div class="gbemu-example"><b>Example.</b> The clock reads 10:47. Set register 6 to 4 (operation 2) and register 7 to 6, then select <code>0C</code> and read <code>0xA000</code>: <code>0xF7</code>; select <code>0D</code> and read: <code>0xF4</code>.</div>' +
    '<div class="gbemu-rule" id="gbr-H-10-23"><b>Rule H.10/23. The clock&rsquo;s pages, register by register</b> (each a 4-bit nibble, masked to the width given when written):' +
    '<table class="gbemu-table"><thead><tr><th>Register (hex)</th><th>Timer page (page 0), width in bits</th><th>Alarm page (page 1), width in bits</th></tr></thead><tbody>' +
    '<tr><td>0</td><td>seconds units, 4</td><td>0</td></tr>' +
    '<tr><td>1</td><td>seconds tens, 3</td><td>0</td></tr>' +
    '<tr><td>2</td><td>minutes units, 4</td><td>as the timer page</td></tr>' +
    '<tr><td>3</td><td>minutes tens, 3</td><td>as the timer page</td></tr>' +
    '<tr><td>4</td><td>hours units, 4</td><td>as the timer page</td></tr>' +
    '<tr><td>5</td><td>hours tens, 2; in 12-hour mode bit 1 is PM</td><td>as the timer page</td></tr>' +
    '<tr><td>6</td><td>weekday, 3</td><td>as the timer page</td></tr>' +
    '<tr><td>7</td><td>day units, 4</td><td>as the timer page</td></tr>' +
    '<tr><td>8</td><td>day tens, 2</td><td>as the timer page</td></tr>' +
    '<tr><td>9</td><td>month units, 4</td><td>0</td></tr>' +
    '<tr><td>A</td><td>month tens, 1</td><td>the 24-hour flag, 1</td></tr>' +
    '<tr><td>B</td><td>year units, 4</td><td>the leap-year counter, 2 (0 = leap year)</td></tr>' +
    '<tr><td>C</td><td>year tens, 4</td><td>0</td></tr>' +
    '<tr><td>D</td><td>page and flags</td><td>0</td></tr>' +
    '</tbody></table>' +
    'Pages 2 and 3 are free, every register 4 bits. The timer page holds seconds, minutes and hours as two decimal digits each, the weekday, day, month and year as decimal digits, and a flags register; the alarm page holds the 24-hour flag and a leap-year counter.</div>' +
    '<div class="gbemu-rule" id="gbr-H-10-24"><b>Rule H.10/24. The carries, exactly.</b> The clock counts seconds in emulated time (one clock second as in Rule H.5/4) while it runs, and carries through the days of each month, February 29 days when the leap counter is 0, years 00 to 99:' +
    '<ol class="gbemu-steps">' +
    '<li>Seconds and minutes roll at 60.</li>' +
    '<li>Hours: in 24-hour mode they run 0 to 23; in 12-hour mode the hours digits hold 0 to 11 (0 is twelve o&rsquo;clock) with bit 1 of the hours-tens register set for PM, and the day passes when 11 PM rolls to 0 with PM clear.</li>' +
    '<li>At each day change the weekday steps (0 to 6, then 0) and the day steps; past the month&rsquo;s length the day becomes 1 and the month steps.</li>' +
    '<li>Past 12 the month becomes 1, the year steps (99 to 00) and <b>the leap-year counter steps up by 1, wrapping from 3 to 0</b>, at that same carry and nowhere else.</li>' +
    '</ol>' +
    '<b>At power-on every page register is 0</b> (cartridge RAM rule), day 00 and month 00 included, and nothing corrects them: the calendar simply counts from there, a month outside 1 to 12 being 31 days long. The calendar is advanced by the time away (Rule H.9/1).</div>' +
    '<div class="gbemu-example"><b>Example.</b> From power-on (day 00, month 00): day 00 steps to 01 at the first day change, and month 00 steps to 01 when that 31-day month runs out. In 12-hour mode, 11:59:59 PM (hours 11, PM set) is followed by 0:00:00 with PM clear and a new day; 11:59:59 AM is followed by 0:00:00 PM, the same day.</div>' +

    '<p class="gbemu-key"><b>MBC6</b> (<code>20</code>)</p>' +
    '<div class="gbemu-rule" id="gbr-H-10-25"><b>Rule H.10/25. Windows and registers.</b> <code>0000</code>-<code>3FFF</code> is fixed: it always reads the image&rsquo;s first 16&nbsp;KiB. Two 8&nbsp;KiB windows at <code>4000</code> and <code>6000</code>, each cartridge memory or flash; two 4&nbsp;KiB RAM windows at <code>A000</code> and <code>B000</code>. At power-on the window at <code>4000</code> shows cartridge-memory bank 2 and the window at <code>6000</code> bank 3 (banks of 8&nbsp;KiB). Mapper writes:' +
    '<table class="gbemu-table"><thead><tr><th>Write address (hex)</th><th>Register</th></tr></thead><tbody>' +
    '<tr><td><code>0000</code>-<code>1FFF</code>, address bits 10 to 12 = 0</td><td>the RAM enable: <code>v</code> = <code>0x0A</code> opens (the whole byte), any other value shuts</td></tr>' +
    '<tr><td>bits 10 to 12 = 1</td><td>the 4&nbsp;KiB RAM bank at <code>A000</code> (3 bits)</td></tr>' +
    '<tr><td>bits 10 to 12 = 2</td><td>the 4&nbsp;KiB RAM bank at <code>B000</code> (3 bits)</td></tr>' +
    '<tr><td>bits 10 to 12 = 3</td><td>the flash enable (bit 0)</td></tr>' +
    '<tr><td>bits 10 to 12 = 4</td><td>the flash write enable (bit 0)</td></tr>' +
    '<tr><td>bits 10 to 12 = 5 to 7</td><td>ignored</td></tr>' +
    '<tr><td><code>2000</code>-<code>27FF</code></td><td>the 8&nbsp;KiB bank of the window at <code>4000</code> (7 bits)</td></tr>' +
    '<tr><td><code>2800</code>-<code>2FFF</code></td><td>what that window maps: bit 3 set, flash; clear, cartridge memory</td></tr>' +
    '<tr><td><code>3000</code>-<code>37FF</code>, <code>3800</code>-<code>3FFF</code></td><td>the same two for the window at <code>6000</code></td></tr>' +
    '</tbody></table>' +
    'Reads of a flash window with the flash disabled return <code>0xFF</code>. The flash is the host&rsquo;s buffer (1&nbsp;MiB, the chip&rsquo;s size); with no buffer it reads <code>0xFF</code> and programming is dropped. A flash address is the window&rsquo;s bank &times; 8&nbsp;KiB + the window offset.</div>' +
    '<div class="gbemu-rule" id="gbr-H-10-26"><b>Rule H.10/26. The flash commands, exactly.</b> A write into a window that maps flash, with the flash enabled, goes to the flash command logic. Offsets are window offsets (the address less the window&rsquo;s start):' +
    '<ol class="gbemu-steps">' +
    '<li>Unlock: <code>AA</code> written at window offset <code>1555</code>, then <code>55</code> at offset <code>0AAA</code>.</li>' +
    '<li>Then the command byte at <em>any</em> offset of a flash window: <code>90</code> identify (reads give <code>C2</code> at even and <code>81</code> at odd addresses), <code>A0</code> program, or <code>80</code> followed by a second <code>AA</code>/<code>55</code> pair (as step 1) and <code>30</code> (erase the 128&nbsp;KiB sector the write&rsquo;s address is in) or <code>10</code> (erase the whole chip).</li>' +
    '<li>A wrong byte or offset anywhere in a sequence returns it to the start. <code>F0</code> at any time ends every mode (reset).</li>' +
    '<li><b>After <code>A0</code></b> the chip stays in program mode until <code>F0</code>: every later write to a flash window programs that byte (AND into it: programming only clears bits), and reads return the array as it now stands.</li>' +
    '<li><b>After an erase</b> (done at once) reads return the status byte <code>80</code> until <code>F0</code>.</li>' +
    '</ol>' +
    'Without the flash write enable, sector 0 (the first 128&nbsp;KiB) is neither programmed nor erased; the other sectors do not need it.</div>' +
    '<div class="gbemu-example"><b>Example.</b> Window <code>4000</code> maps flash bank 9, the flash is enabled. Writes: <code>AA</code> to <code>0x5555</code> (offset <code>1555</code>), <code>55</code> to <code>0x4AAA</code> (offset <code>0AAA</code>), <code>A0</code> to <code>0x4000</code>, then <code>0x0F</code> to <code>0x4010</code>: flash address 9 &times; <code>0x2000</code> + <code>0x10</code> = <code>0x12010</code>, in sector 0, so without the flash write enable it stays as it was; with it, a byte <code>0xF3</code> there becomes <code>0x03</code>.</div>' +

    '<p class="hw-readable">Beyond these, the core plays a number of unlicensed boards (multicarts and several unlicensed publishers&rsquo; own mappers, recognised by their own marks). <b>This page does not specify them</b>; an implementer working from it alone will not run those cartridges, and no board row covers any of them.</p>' +

    '<h4 class="gbemu-sub">H.11: Boards named per file, and the Gowin logo switch</h4>' +
    '<p class="hw-readable">Some dumps do not say which board they came from: the header names the wrong chip, or the maker left no mark. For these the core keeps a short table keyed by the CRC-32 and size of the whole file, and each row names its source. It does not change any other file.</p>' +
    '<div class="gbemu-rule" id="gbr-H-11-1"><b>Rule H.11/1.</b> A file whose length and CRC-32 match a row of the key table below runs on the board its row names:' +
    '<table class="gbemu-table"><thead><tr><th>Files</th><th>Board</th><th>Source, label</th></tr></thead><tbody>' +
    '<tr><td>Pocket Monsters Kin and Gin, Spaceworld 1997 demos (4)</td><td>MBC3 with its clock (the header says MBC1)</td><td>another emulator&rsquo;s override list names all four by header; FITTED</td></tr>' +
    '<tr><td>Story of Lasama</td><td>two 64&nbsp;KiB halves (bit 1 of a write to exactly <code>6000</code> while bit 7 is clear) and a 16&nbsp;KiB bank inside the half (bits 0-1 of a write to exactly <code>2080</code>, 0 allowed). Both are single addresses, not ranges: a write anywhere else in <code>0000</code>-<code>7FFF</code> changes nothing (read from our source). The low window is the half&rsquo;s first bank</td><td>another emulator&rsquo;s software list and board; FITTED</td></tr>' +
    '<tr><td>Chongwu Xiao Jingling</td><td>MBC5; the first read of <code>41C3</code> after power-on returns <code>5D</code></td><td>a reference emulator; FITTED</td></tr>' +
    '<tr><td>Guaishou Go! Go! II, Koudai Guaishou - Dongzuo Pian</td><td>New GB Color HK0701/HK0819: bit 7 of the bank write turns <code>4000-4FFF</code> into an answer computed from address lines A4-A11 (eight functions chosen by A4-A6) and <code>5000-7FFF</code> into open bus</td><td>two other emulators agree; FITTED</td></tr>' +
    '<tr><td>Yingxiong Tianxia</td><td>Li Cheng (an MBC5 that ignores writes to <code>2101-2FFF</code>)</td><td>two other emulators agree; FITTED</td></tr>' +
    '<tr><td>Koudai Guaishou - Da Jihe</td><td>the GGB-81 data-line crossbar (mode written to <code>2001</code>), MBC5 banking, 32&nbsp;KiB RAM</td><td>measured: it runs only on this table; FITTED</td></tr>' +
    '<tr><td>Gedou Jian Shen KF, Sanguozhi - Aoshi Tianxia</td><td>Vast Fame VF001 whose protection session starts from <code>10</code> instead of 0</td><td>another emulator&rsquo;s mode for these releases, measured; FITTED</td></tr>' +
    '<tr><td>Rocman X Gold + 4 in 1</td><td>Sachen MMC2 with the solder pad that leaves outer banks with bit 6 unconnected (they read open bus)</td><td>another emulator, measured; FITTED</td></tr>' +
    '</tbody></table></div>' +
    '<div class="gbemu-rule" id="gbr-H-11-2"><b>Rule H.11/2. The keys, so a build can recognise the same files.</b> Each row above is matched on the whole file&rsquo;s length and its CRC-32 (the common one: reflected polynomial <code>0xEDB88320</code>, initial value all ones, final value inverted, over every byte of the file); a file is checked only if its length matches a row. These are identification values for the dumps, not data from them.' +
    '<table class="gbemu-table"><thead><tr><th>File</th><th>Length (bytes)</th><th>CRC-32 (hex)</th></tr></thead><tbody>' +
    '<tr><td>Pocket Monsters Gin (Demo) (Spaceworld 1997)</td><td>1 MiB (0x100000)</td><td><code>7246170A</code></td></tr>' +
    '<tr><td>Pocket Monsters Gin (Demo) (Spaceworld 1997) (Debug)</td><td>1 MiB</td><td><code>2C5732DB</code></td></tr>' +
    '<tr><td>Pocket Monsters Kin (Demo) (Spaceworld 1997)</td><td>1 MiB</td><td><code>ABEDD2BF</code></td></tr>' +
    '<tr><td>Pocket Monsters Kin (Demo) (Spaceworld 1997) (Debug)</td><td>1 MiB</td><td><code>C2CA5626</code></td></tr>' +
    '<tr><td>Lasama Chuanqi - Story of Lasama (Taiwan)</td><td>128 KiB (0x20000)</td><td><code>989A5FE0</code></td></tr>' +
    '<tr><td>Chongwu Xiao Jingling - Jiejin Ta Zhi Wang (Taiwan)</td><td>1 MiB</td><td><code>620E785D</code></td></tr>' +
    '<tr><td>Guaishou Go! Go! II (Taiwan)</td><td>1 MiB</td><td><code>B0237467</code></td></tr>' +
    '<tr><td>Koudai Guaishou - Dongzuo Pian (Taiwan) (En)</td><td>1 MiB</td><td><code>14355371</code></td></tr>' +
    '<tr><td>Yingxiong Tianxia (Taiwan) (Zh)</td><td>2 MiB (0x200000)</td><td><code>5F2D6317</code></td></tr>' +
    '<tr><td>Koudai Guaishou - Da Jihe (Taiwan) (Ja)</td><td>2 MiB</td><td><code>A96E26C4</code></td></tr>' +
    '<tr><td>Gedou Jian Shen KF (Taiwan) (En)</td><td>1 MiB</td><td><code>190702B3</code></td></tr>' +
    '<tr><td>Sanguozhi - Aoshi Tianxia (Taiwan)</td><td>1 MiB</td><td><code>48D2607F</code></td></tr>' +
    '<tr><td>Rocman X Gold + 4 in 1 (Taiwan)</td><td>512 KiB (0x80000)</td><td><code>7E1351CF</code></td></tr>' +
    '</tbody></table></div>' +
    '<div class="gbemu-why"><b>Why.</b> <b>Four of these boards are named, not specified</b>: the New GB Color HK0701/HK0819 answer functions, the GGB-81 crossbar modes, the Vast Fame VF001 protection session and the Sachen MMC2 solder-pad board. Their rows say what each board is and where its behaviour was learned, but this page does not give their logic, so (as with H.10&rsquo;s unlicensed boards) a build from this page alone will not run those files. No board row covers any of them.</div>' +
    '<div class="gbemu-rule" id="gbr-H-11-3"><b>Rule H.11/3. The Gowin logo switch.</b> <i>Prince Yeh Rude</i> holds its maker&rsquo;s logo at <code>0104</code> and the Nintendo logo at <code>0084</code>. The board answers the logo <i>check</i> from <code>0084</code> (it holds A7 low) after the first pass, which draws the logo, read <code>0104</code> straight. <b>Recognised</b> by &ldquo;GOWIN&rdquo; at the start of the title with the logo only at <code>0084</code>; one file in the library. <b>Exactly, without printing the logo</b>: the image is at least 32&nbsp;KiB, the title at <code>0x134</code> starts with the five letters GOWIN, the 48 bytes at <code>0x104</code> do <em>not</em> have the CRC-32 <code>46195417</code> and the 48 bytes at <code>0x084</code> do (that value is the CRC-32 of the Nintendo logo block, the same identification value H.11&rsquo;s table uses; the logo itself is not printed here). <b>The phases</b>, only when a boot program is supplied:' +
    '<ol class="gbemu-steps">' +
    '<li><b>Show</b>: reads of <code>0100</code>-<code>01FF</code> are counted and return the cartridge&rsquo;s own bytes. After 48 such reads, or at once on any write to work memory (<code>C000</code>-<code>DFFF</code>, which the Color boot program makes before its check), the board moves to phase 2.</li>' +
    '<li><b>Check</b>: reads of <code>0104</code>-<code>0133</code> return the byte <code>0x80</code> lower (<code>0084</code>-<code>00B3</code>), again for 48 reads of <code>0100</code>-<code>01FF</code>, the counter starting from 0.</li>' +
    '<li><b>Off</b>: every read is straight.</li>' +
    '</ol>' +
    '<b>Which reads count</b>: every read of <code>0100</code>-<code>01FF</code> that reaches the cartridge, whoever makes it: the processor&rsquo;s (opcode fetches included), a sprite-memory transfer&rsquo;s and a Colour block transfer&rsquo;s (each of its source bytes). <b>Which writes move it to phase 2</b>: a processor write to <code>C000</code>-<code>DFFF</code> only; a write to the echo at <code>E000</code>-<code>FDFF</code> stores into work memory but does not move the switch.</div>' +
    '<div class="gbemu-example"><b>Example.</b> With no write to work memory: reads 1 to 48 of <code>0100</code>-<code>01FF</code> return the cartridge&rsquo;s own bytes; reads 49 to 96 are check reads, so a read of <code>0x0110</code> among them returns the byte at <code>0x0090</code>, while a read of <code>0x0140</code> (outside <code>0104</code>-<code>0133</code>) returns its own byte; from read 97 every read is straight. If a work-memory write comes after read 10, phase 2 starts at that write and counts its own 48 reads from 0.</div>' +
    '<div class="gbemu-why"><b>Why.</b> The boot program would refuse that header. MECHANISM: that the switch exists and which block it reads. FITTED: the timing (48 header reads per phase; the Color boot program&rsquo;s work-RAM write starts the check phase). Read from our source.</div>' +
    '<p class="hw-readable"><b>Not built, because nothing documents them:</b> the command port that <i>Zook Z</i> and <i>Super Fighters S</i> use (strings written to <code>7080</code>, answers read from <code>A080</code>), the read-back register of <i>Dragon Ball - Final Bout</i> (<code>2300</code> and <code>4000</code>), and the boards of the <i>Zelda DX</i> betas, <i>Mythri</i> and the <i>Tyrannosaurus Tex</i> prototype.</p>' +
    '</section>' +

  '</div>';
}
